-- Node: ab-treatment (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Treatment Considerations","body":"**Sodium Bicarbonate:**\n[Sodium Bicarbonate](#/drug/sodium-bicarbonate/metabolic acidosis) — indications, dosing, and evidence.\n\n**Indications for bicarbonate:** [12][17][19]\n• pH ≤ 7.20 with moderate-to-severe AKI — reasonable, but recent evidence tempers the benefit. BICAR-ICU (2018) suggested a mortality signal in the AKI subgroup; the confirmatory BICARICU-2 trial (JAMA 2025, n=627) found NO day-90 mortality difference (62.1% vs 61.7%). The consistent benefit is RRT-sparing (dialysis in 35% vs 50%). Use to buy time / reduce dialysis, not as a proven mortality intervention.\n• TCA overdose (sodium channel blockade)\n• Salicylate toxicity (urinary alkalinization)\n• Life-threatening hyperkalemia\n• Bicarbonate-losing conditions (severe diarrhea, RTA)\n\n**Note:** Both BICAR-ICU trials enrolled pH ≤ 7.20 + moderate-to-severe AKI. For DKA specifically the current threshold is pH < 7.0 (2024 ADA/EASD/JBDS/AACE/DTS consensus); pH < 6.9 was the superseded 2009 ADA figure. Neither number rests on outcome data. [20]\n\n**NOT recommended:** [3][17]\n• Routine cardiac arrest or CPR\n• Routine DKA (consider only if pH < 7.0 per the 2024 ADA/EASD consensus; no proven benefit) [20]\n• Routine lactic acidosis (no hemodynamic benefit proven)\n\n[Fluid Selection Guide](#/info/ab-fluids-guide) — NS vs balanced crystalloids.","citation":[1,2,3,12,13,17,19,20],"next":"ab-disposition","calculatorLinks":[{"id":"anion-gap","label":"Anion Gap"},{"id":"stewart-sig","label":"Stewart SID/SIG"}],"summary":"Bicarb for pH≤7.20 with AKI (RRT-sparing, no mortality benefit per BICARICU-2), TCA OD, salicylate tox, severe hyperK — NOT routine in DKA or lactic acidosis","safetyLevel":"warning"}'::jsonb
WHERE id = 'ab-treatment' AND tree_id = 'acid-base';

