-- Node: bb-agent-specific (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Agent-Specific Considerations","body":"**PROPRANOLOL** — The Dangerous One:\n• Most lipophilic — crosses BBB easily\n• **Sodium channel blockade** → QRS widening (like TCA)\n• Seizures common\n• **Treat QRS >100ms with [Sodium Bicarbonate](#/drug/sodium-bicarbonate/propranolol) 1-2 mEq/kg** [1][2]\n\n**SOTALOL** — The Arrhythmogenic One:\n• Class III antiarrhythmic effect (K+ channel blockade)\n• **QT prolongation** → Torsades de pointes risk\n• Monitor QTc closely\n• Have [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades) 2g IV ready [1]\n• May require overdrive pacing for Torsades\n\n**CARVEDILOL** — The Hypotensive One:\n• Combined alpha + beta blockade\n• More profound hypotension due to alpha-1 blockade\n• May need higher vasopressor doses [1]\n\n**ATENOLOL/NADOLOL** — Hydrophilic:\n• Less CNS effects\n• Small volume of distribution\n• **Dialyzable** — consider hemodialysis in severe cases [1][3]","citation":[1,2,3],"next":"bb-stabilize","calculatorLinks":[{"id":"bb-agent-guide","label":"Agent-Specific Guide"}],"summary":"Propranolol: QRS widening → NaHCO3; Sotalol: QT/Torsades → Mg + pacing; Carvedilol: alpha block → worse hypotension","safetyLevel":"critical"}'::jsonb
WHERE id = 'bb-agent-specific' AND tree_id = 'beta-blocker-od';

-- Node: bb-sotalol (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Sotalol — QT Prolongation & Torsades","body":"**Sotalol** has Class III antiarrhythmic effects (K+ channel blockade) [1].\n\n**Unique risks:**\n• QT prolongation\n• Torsades de pointes\n• Delayed arrhythmias (may occur hours after ingestion)\n\n**Management:**\n• **[Magnesium Sulfate](#/drug/magnesium-sulfate/torsades)** 2g IV over 2-5 min — give prophylactically if QTc prolonged\n• For Torsades: Mag 2g IV push, repeat 2g at 5-15 min if it persists, then a continuous infusion (a bolus alone wears off) + **overdrive pacing** (set rate 100-120 bpm to suppress)\n• Isoproterenol infusion to increase heart rate if pacing unavailable\n• **Avoid amiodarone** — further QT prolongation\n\n**Monitoring:**\n• Extended observation (24-48h) — delayed arrhythmias possible\n• Continuous telemetry essential","citation":[1],"next":"bb-disposition","treatment":{"firstLine":{"drug":"Magnesium Sulfate","dose":"2g","route":"IV over 2-5 min","frequency":"Repeat PRN, then 1-2g/hr infusion","duration":"Until QTc normalizes","notes":"Give prophylactically if QTc prolonged. Overdrive pace for Torsades."},"monitoring":"Continuous telemetry. QTc on serial ECGs. Mg level."},"summary":"Sotalol: Mg 2g IV prophylactically if QTc prolonged + overdrive pacing for Torsades — AVOID amiodarone (further QT prolongation)","safetyLevel":"critical"}'::jsonb
WHERE id = 'bb-sotalol' AND tree_id = 'beta-blocker-od';

-- Node: bt-metabolic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Metabolic Complications","body":"**METABOLIC COMPLICATIONS OF TRANSFUSION**\n\n**HYPOCALCEMIA (Citrate Toxicity):**\n- Citrate anticoagulant chelates ionized calcium\n- Risk factors: Massive transfusion, liver dysfunction\n- iCa <1.1 mmol/L associated with mortality\n\n**Effects of hypocalcemia:**\n- Impairs coagulation cascade (factors need Ca2+)\n- Impairs platelet function\n- Cardiac depression (QT prolongation, arrhythmias)\n\n**Treatment:**\n- See Calcium Protocol → [next]\n\n---\n\n**HYPERKALEMIA:**\n- Stored RBCs leak K+ into plasma\n- Irradiation accelerates K+ leak\n- **Pediatric risk highest** (smaller volume distribution)\n\n**Treatment:**\n- Dextrose 0.5-1 g/kg + insulin 0.1 units/kg IV\n- Adult: insulin 5 units IV (or 0.1 units/kg, max 10) if eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n- Adult: insulin 10 units IV only if normal renal function AND adequate glucose\n- Give WITH 25 g dextrose (D50 50 mL) unless glucose >250 mg/dL\n- Check glucose at 30, 60, 120 and 240 min\n- Monitor ECG (peaked T-waves, wide QRS)\n- Consider calcium for cardiac protection\n\n---\n\n**HYPOTHERMIA:**\n- Cold blood products drop core temp\n- Hypothermia worsens coagulopathy\n**Prevention:** Warm all products during massive transfusion","citation":[9,10],"options":[{"label":"Calcium Protocol","next":"bt-calcium"},{"label":"Back to Complications","next":"bt-complications-overview"}],"summary":"Metabolic: hypocalcemia (citrate) → impairs clotting/cardiac; hyperkalemia (esp peds); hypothermia worsens coagulopathy"}'::jsonb
WHERE id = 'bt-metabolic' AND tree_id = 'blood-transfusions';

