INSERT INTO tree_citations (tree_id, num, text) VALUES ('chs', 15, 'Perkins J et al. American Academy of Emergency Medicine position statement: safety of droperidol use in the emergency department. J Emerg Med. 2015;49(1):91-97. Concluded droperidol is effective and safe for nausea, headache and agitation; the literature did not support mandating an ECG or telemetry monitoring for doses <2.5 mg IM or IV.');
