INSERT INTO tree_citations (tree_id, num, text) VALUES ('chs', 17, 'Droperidol injection, USP: US prescribing information. American Regent, Inc.; revised 2023. DailyMed SPL setid 147e033d-d997-4ef6-8bb5-a9ba372590b2. Boxed warning: QT prolongation and/or torsade de pointes reported at or below recommended doses, some cases fatal. All patients should undergo a 12-lead ECG prior to administration (prolonged = QTc >440 msec males, >450 msec females); if prolonged, droperidol should NOT be administered. Onset of single IM and IV doses three to ten minutes. Maximum recommended initial dose 2.5 mg IM or slow IV, with additional 1.25 mg doses given with caution. Use in CHS is off-label.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('chs', 18, 'ZYPREXA (olanzapine) tablet, ZYPREXA ZYDIS (olanzapine) orally disintegrating tablet, ZYPREXA IntraMuscular (olanzapine) injection: US prescribing information. H2-Pharma LLC; 2026. DailyMed SPL setid b418946a-1ab4-4d89-a012-d94fc361a3c4. ECG Changes: in pooled studies of adults and of adolescents there were no significant differences between olanzapine and placebo in the proportions of patients experiencing potentially important changes in ECG parameters, including QT, QTc (Fridericia corrected) and PR intervals. IM dose for agitation 10 mg (5 mg or 7.5 mg when clinically warranted). Boxed warning: increased mortality in elderly patients with dementia-related psychosis. Use in CHS is off-label.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('chs', 20, 'Gajendran M et al. CHS: definition, pathophysiology, clinical spectrum, insights into acute and long-term management. J Investig Med. 2020;68(8):1309-1316.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('chs', 22, 'Haloperidol injection, USP (haloperidol lactate) 5 mg/mL: US prescribing information. Hikma Pharmaceuticals USA Inc.; revised 2024. DailyMed SPL setid 8397a841-f240-4767-9dcd-781e6d3f7c7f. Label states that haloperidol injection is NOT approved for intravenous administration; that higher than recommended doses of any formulation and intravenous administration appear to be associated with a higher risk of QTc prolongation and Torsades de Pointes; that a QTc interval exceeding 500 msec is associated with an increased risk of Torsades de Pointes; and that if haloperidol is administered intravenously the ECG should be monitored for QTc prolongation and arrhythmias. Boxed warning: increased mortality in elderly patients with dementia-related psychosis. IV use in CHS is off-label.');

-- Node: dka-severe-pathway (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Severe DKA — Immediate Management","body":"**Severe DKA (pH <7.0, HCO3 <10) requires aggressive, immediate intervention:**\n\n**Immediate actions (parallel, do NOT delay):**\n• **IV access:** Two large-bore IVs, continuous cardiac monitor\n• **Labs:** VBG, CBC, BMP, lactate, BOHB, cultures, UA, EKG\n• **Fluids:** **Normal saline** 500-1000 mL IV bolus over 30-60 min. Reassess HR, BP, perfusion.\n• **Insulin:** Consider 10 U IV bolus IF: serum K <5.3 AND pH <6.9 AND delay to insulin drip. Otherwise start drip immediately (see Module 5). [1]\n• **Potassium:** Check K level STAT. If <3.3, HOLD insulin and replete K first (critical). If 3.3-5.3, start K repletion concurrent with insulin. [1]\n• **Bicarbonate:** NOT routine at any pH — fluids, insulin and potassium are definitive and no trial has shown benefit. The 2024 ADA/EASD/JBDS/AACE/DTS consensus considers bicarbonate only if acidosis is severe (pH <7.0), superseding the 2009 pH <6.9 threshold. If given: **100 mmol (100 mL of 8.4%) in 400 mL sterile water — an ISOTONIC infusion — q2h until pH >7.0.** Do NOT push undiluted 8.4%. [1,12]\n\n**Disposition:** ICU admission mandatory.\n**Monitoring:** Reassess labs q1-2h initially.","citation":[1,2,5],"next":"dka-precipitant-screen","treatment":{"firstLine":{"drug":"Normal saline","dose":"500-1000 mL","route":"IV","frequency":"Bolus over 30-60 min","duration":"Initial resuscitation","notes":"Reassess HR, BP, perfusion after bolus. Repeat if needed."},"alternative":{"drug":"Sodium bicarbonate 8.4% (diluted to isotonic)","dose":"100 mmol (100 mL of 8.4%) in 400 mL sterile water","route":"IV","frequency":"Infuse over ~2 h; may repeat q2h until pH >7.0","duration":"Stop once pH >7.0; recheck VBG q2h","notes":"Not routine. Consider only if pH <7.0 per the 2024 ADA/EASD consensus (supersedes the 2009 pH <6.9 threshold). No mortality, cardiac or neurologic benefit has been demonstrated. Never push undiluted 8.4%."},"monitoring":"Continuous cardiac monitor. Labs q1-2h. ICU admission mandatory."},"summary":"pH <7.0 = immediate parallel resuscitation: 2 IVs, NS bolus, check K+ before insulin, ICU.","safetyLevel":"critical"}'::jsonb
WHERE id = 'dka-severe-pathway' AND tree_id = 'dka';

-- Node: dka-special-protocol (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Special Population Management Overview","body":"**High-risk populations require protocol modifications to prevent harm:**\n\n**Hemodialysis patients:**\n• Problem: Often euvolemic/hypervolemic; aggressive fluid resuscitation causes volume overload, pulmonary edema, hypertension\n• Solution: Target fluid resuscitation carefully; may only need insulin + modest fluids + dextrose\n• Insulin: Same 0.1 U/kg/hr drip protocol\n• Dialysis: Consider during severe DKA for K removal, HCO3 correction, acidosis clearance\n• Potassium: Very restricted; use [potassium acetate](#/drug/potassium-acetate/DKA) preferentially over KCl\n• Resolution marker: Use BOHB <1 mmol/L, not AG normalization (AG may not normalize in renal disease)\n\n**SGLT2 inhibitor-associated & Euglycemic DKA:**\n• Discontinue SGLT2i permanently — high recurrence risk\n• Lower glucose threshold for suspicion (<200 acceptable)\n• Same insulin + fluid protocol as classic DKA\n• Earlier basal glargine to prevent recurrence\n\n**Pregnancy:**\n• Higher risk, lower glucose threshold\n• Continuous fetal monitoring\n• Obstetric & endocrinology co-management\n• Insulin demand increases significantly in third trimester — may need 10-20 U/kg/day\n• Avoid bicarbonate — not routine at any pH; consider only if pH <7.0 (2024 ADA/EASD), and then only as the isotonic 100 mmol-in-400 mL preparation\n\n**Insulin pump users:**\n• Rapid onset — often severe at presentation (4-8h from failure to severe DKA)\n• [Detailed pump troubleshooting protocol](#node/dka-insulin-pump) in Module 7\n• Check pump function, infusion site, reservoir, tubing\n• Aggressive insulin dosing (IV drip + basal glargine early)\n• Decision: suspend pump vs continue with increased basal\n\n**Details for each path available in Module 7.**","citation":[1,10,11,13,14],"next":"dka-precipitant-screen","summary":"HD = restrict fluids/K+. SGLT2i = permanently discontinue. Pregnancy = fetal monitoring + OB/endo.","safetyLevel":"warning"}'::jsonb
WHERE id = 'dka-special-protocol' AND tree_id = 'dka';

-- Node: dka-hypokalemia-protocol (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Hypokalemia Management (K <3.3)","body":"**CRITICAL: Do NOT start insulin until K >3.3 — fatal arrhythmias if K falls further.**\n\n**Aggressive potassium repletion:**\n• **[Potassium chloride (KCl)](#/drug/potassium-chloride-iv/DKA) IV:** 10 mEq/hr — this is a RATE, not a concentration in the bag [1]\n• Up to 10-20 mEq/hr ONLY with central venous access + continuous cardiac monitoring; peripheral ceiling is 10 mEq/hr at a maximum concentration of 40 mEq/L [1]\n• Potassium acetate may be substituted if preferring to avoid Cl load\n• Goal: Bring K to 3.3-3.5 before insulin starts\n• Check K q1-2h during repletion — often need 40-80 mEq to raise K by 0.5-1 mEq/L\n• Do NOT trust estimates — must recheck lab\n\n**Oral potassium (if tolerating PO):**\n• [Potassium chloride solution or salt substitute](#/drug/potassium-chloride-oral/DKA) 60 mEq q2-4h\n• Much slower but useful adjunct if GI tolerant\n\n**Cardiac monitoring:**\n• Continuous monitor if possible\n• Watch for peaked T-waves, prolonged PR\n• Do NOT rely on EKG — renal or acid-base factors affect threshold\n\n**When insulin becomes safe:**\n• Once K >3.3, proceed to insulin protocol\n• But continue aggressive K repletion SIMULTANEOUSLY\n• Insulin lowers K rapidly once given — need replacement drip running during insulin infusion\n\n**Time consideration:** May delay insulin 1-2 hours to replete K — this is appropriate and safer than rushing insulin with low K.","citation":[1,5,12],"next":"dka-k-repleted","treatment":{"firstLine":{"drug":"Potassium chloride (KCl)","dose":"10 mEq/hr IV (10-20 mEq/hr only via central line with cardiac monitor)","route":"IV","frequency":"Continuous infusion","duration":"Until K >3.3 mEq/L","notes":"This is a RATE, not a bag concentration. Peripheral maximum 10 mEq/hr (max concentration 40 mEq/L); 10-20 mEq/hr requires central access + continuous cardiac monitoring. HOLD insulin until K >3.3."},"alternative":{"drug":"Potassium chloride oral","dose":"40-60 mEq","route":"PO","frequency":"q2-4h","duration":"Adjunct to IV if tolerating PO","notes":"Slower absorption. Use as supplement to IV if patient tolerating oral intake."},"monitoring":"Continuous cardiac monitor. K level q1-2h during aggressive repletion. EKG for peaked T-waves, prolonged PR. Do NOT start insulin until K >3.3."},"summary":"KCl 10 mEq/hr IV (10-20 mEq/hr only via central line) until K+ >3.3. Do NOT start insulin until repleted — fatal arrhythmia risk.","safetyLevel":"critical"}'::jsonb
WHERE id = 'dka-hypokalemia-protocol' AND tree_id = 'dka';

-- Node: dka-k-repleted (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"K Repleted — Now Safe for Insulin","body":"**Once K >3.3, insulin infusion can now be started safely.**\n\nBut REMEMBER: Insulin will lower K further. You must:\n• Continue potassium supplementation DURING insulin therapy\n• Target serum K 4-5 mEq/L during acute phase; withhold potassium once K >5.0 (normal renal function) [1]\n• Check K q1-2h × 4-6 hrs, then q4h\n• Adjust K supplementation based on trending\n\n**Proceed to DKA insulin protocol (next node).**","citation":[1,5],"next":"dka-insulin-start","summary":"K+ now >3.3 — safe to start insulin, but continue K+ repletion concurrently. Target K+ >5 during treatment."}'::jsonb
WHERE id = 'dka-k-repleted' AND tree_id = 'dka';

-- Node: dka-electrolytes-monitor (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Electrolyte Management & Monitoring","body":"**Aggressive potassium and phosphate/magnesium repletion is essential to prevent complications.**\n\n**Potassium Target:**\n• Goal: Maintain K 4-5 mEq/L during acute DKA; withhold potassium once K >5.0 (normal renal function) [1]\n• Aggressive repletion: [Potassium acetate](#/drug/potassium-acetate/DKA) IV (preferred over KCl to reduce chloride load and NAGMA risk) or [potassium chloride](#/drug/potassium-chloride-iv/DKA)\n• IV: add 20-30 mEq of potassium per LITRE of IV fluid — a CONCENTRATION in the bag, not an hourly rate [1]\n• Infusion RATE ceiling is separate: 10 mEq/hr peripherally (max 40 mEq/L), 10-20 mEq/hr only with central access + continuous cardiac monitoring\n• Oral potassium citrate 60 mEq q2-4h if tolerating PO\n• Check K q1-2h × 6 hours, then q4h minimum\n\n**Magnesium & Phosphate:**\n• Check both on admission and q4-6h during acute phase\n• Repletion needed: Mg <1.5 mg/dL or Phos <1.5 mg/dL\n• [Magnesium sulfate](#/drug/magnesium-sulfate/DKA): 1-2 g IV over 10-15 min (recheck after 2-4 hrs) [1]\n• Phosphate repletion: Often done PO if tolerating (potassium phosphate salt, 30 mmol q2-4h) or IV if severe. Potassium content differs by product — oral neutral phosphate tablets are sodium-dominant (about 1.1 mEq K per tablet), while IV [potassium phosphate](#/drug/potassium-phosphate/DKA phosphate repletion) delivers 1.47 mEq K per mmol phosphorus (30 mmol = 44 mEq K). Count the salt''s potassium against the potassium above\n• Both common in DKA — 25-50% of patients are Mg/Phos depleted\n\n**Thiamine (Vitamin B1):**\n• Give [thiamine](#/drug/thiamine/DKA) 100 mg IV on admission — 25% of DKA patients are thiamine deficient [1]\n• Prevents Wernicke encephalopathy if alcohol history\n\n**Monitoring Schedule:**\n• Glucose: q1-2h × 4h, then q2-4h\n• BMP (Na, K, Cl, HCO3): q2-4h until improving, then q4-6h\n• Mg, Phos, Ca: admission + q4-6h\n• Lactate: q4h if elevated initially\n• VBG: q2-4h to assess pH, HCO3 progress\n• EKG: admission, and if K abnormal\n• BOHB or serum ketones: q4-6h (optional but useful)\n\n**Trend interpretation:**\n• AG should decrease as insulin works (ketones being metabolized)\n• HCO3 should rise gradually\n• Glucose should drop 50-70 mg/dL/hr","citation":[1,2,5],"next":"dka-nagma-screen","treatment":{"firstLine":{"drug":"Potassium chloride or acetate","dose":"20-30 mEq per LITRE of IV fluid","route":"IV","frequency":"Continuous per K level","duration":"Throughout DKA treatment","notes":"CONCENTRATION in the bag, not an hourly rate. Target K 4-5 mEq/L; withhold potassium once K >5.0. Separate RATE ceiling: 10 mEq/hr peripheral, 10-20 mEq/hr only with central access + cardiac monitor."},"alternative":{"drug":"Magnesium sulfate","dose":"1-2 g","route":"IV","frequency":"Over 10-15 min, repeat PRN","duration":"Until Mg >1.5 mg/dL","notes":"Give if Mg <1.5 mg/dL. Recheck in 2-4 hrs. 25-50% of DKA patients are depleted."},"monitoring":"K q1-2h x6h then q4h. Mg/Phos q4-6h. Glucose q1-2h. VBG q2-4h. EKG if K abnormal."},"summary":"Target K+ >5 during treatment. Replace Mg/Phos if low. Give thiamine 100 mg IV on admission."}'::jsonb
WHERE id = 'dka-electrolytes-monitor' AND tree_id = 'dka';

-- Node: dka-nagma-treatment (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"NAGMA Treatment — IV Bicarbonate","body":"**If NAGMA present (Cl >110 or predicted final HCO3 <20), consider IV bicarbonate to speed resolution.**\n\n**Timing:**\n• Usually appears when initial acidosis improving (AG closing) and pH 7.15-7.30 range\n• Can start IV bicarb once AG <12 and HCO3 rising\n• Goal: Raise bicarb to >18-20\n\n**Bicarbonate Dosing Options:**\n\n**Option 1: Isotonic bicarbonate (preferred)**\n• [Sodium bicarbonate](#/drug/sodium-bicarbonate/DKA) 250 mL of isotonic solution (150 mEq/L bicarb in 250 mL D5W) IV at 250 mL/hr\n• Infuse until HCO3 >18-20\n• Gentler, lower hypernatremia risk\n\n**Option 2: Hypertonic bicarbonate (for urgent correction)**\n• [Sodium bicarbonate](#/drug/sodium-bicarbonate/DKA) ampules: 50 mEq in 50 mL (8.4%) IV over 5-10 min\n• Can repeat q2-4h if HCO3 still <18\n• Higher hypernatremia risk — use cautiously\n\n**Monitoring:**\n• Check BMP q2-4h to assess HCO3 rise\n• Watch sodium (risk of hypernatremia from bicarbonate)\n• Continue insulin, K repletion, fluids\n• Often can transition off drip once HCO3 >18\n\n**Controversial — note the scope:** this node is about hyperchloremic NAGMA during DKA recovery, not the ketoacidosis itself. For the ketoacidosis, bicarbonate is not routine at any pH and the 2024 ADA/EASD consensus considers it only if pH <7.0 (superseding the 2009 pH <6.9). Practice for NAGMA varies (some treat at HCO3 <10, some not at all) and no outcome data support either. Use clinical judgment. [1]","citation":[1,2,5,9],"next":"dka-stopping-criteria","treatment":{"firstLine":{"drug":"Sodium bicarbonate isotonic","dose":"150 mEq in 250 mL D5W","route":"IV","frequency":"250 mL/hr","duration":"Until HCO3 >18-20","notes":"Preferred for NAGMA. Lower hypernatremia risk than hypertonic."},"alternative":{"drug":"Sodium bicarbonate 8.4% (hypertonic)","dose":"50 mEq (50 mL ampule)","route":"IV","frequency":"Over 5-10 min, repeat q2-4h PRN","duration":"Until HCO3 >18","notes":"For urgent correction. Higher hypernatremia risk. Use cautiously."},"monitoring":"BMP q2-4h. Watch sodium for hypernatremia. Continue insulin and K repletion. Goal HCO3 >18-20."},"summary":"IV bicarb for NAGMA once AG <12: isotonic preferred, hypertonic if urgent. Watch for hypernatremia."}'::jsonb
WHERE id = 'dka-nagma-treatment' AND tree_id = 'dka';

-- Node: dka-intubation (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Intubation in DKA — Avoid if Possible","body":"**Intubation in DKA is HIGH RISK and generally avoided unless absolutely necessary.** [5]\n\n**Why avoid intubation:**\n• Removal of spontaneous hyperventilation → paradoxical CO2 retention and acidosis worsening\n• Positive pressure ventilation increases PEEP → worse acidosis\n• Risk of post-intubation hypotension despite fluids (loss of sympathetic tone)\n• Aspiration risk if altered MS or vomiting\n• Prolongs ICU stay\n\n**Indications for intubation (rare in pure DKA):**\n• Loss of airway protective reflexes + inability to protect\n• Respiratory failure (RR >35-40 with fatigue, inadequate gas exchange on ABG)\n• Severe altered mental status with risk of aspiration\n• Aspiration event already occurred\n• Septic shock requiring pressors (not DKA alone)\n\n**If intubation unavoidable:**\n\n**Preoperative management:**\n• AGGRESSIVE pre-intubation resuscitation — 1-2L fluid bolus if not already given\n• [Intravenous bicarbonate](#/drug/sodium-bicarbonate/DKA): Not routine — consider only if pH <7.0 (2024 ADA/EASD, superseding the 2009 pH <6.9), given as 100 mmol in 400 mL sterile water (isotonic), not an undiluted push\n• Correct severe hyperkalemia (K >6.5) with insulin bolus\n\n**Drug selection:**\n• Induction: [Ketamine](#/drug/ketamine/induction) preferred (maintains BP, does not worsen acidosis)\n• Avoid propofol (myocardial depression), avoid theophylline derivatives\n\n**Ventilation post-intubation:**\n• High minute ventilation (MV): 12-18 L/min to maintain hyperventilation \n• Large ETT: ≥7.5 to allow high tidal volumes without excessive pressure\n• Mode: Assist-control (not pressure-limited)\n• PEEP: Minimize (0-5 cm H2O)\n\n**Monitoring:** Frequent ABGs (q30min × 2h, then q1-2h), K monitoring, sedation adequate to allow hyperventilation","citation":[1,2,5],"next":"dka-disposition-plan","treatment":{"firstLine":{"drug":"Ketamine","dose":"1-2 mg/kg","route":"IV push","frequency":"Single induction dose","duration":"Induction only","notes":"Preferred induction agent. Maintains BP and does not worsen acidosis. AVOID propofol."},"alternative":{"drug":"Sodium bicarbonate (pre-intubation)","dose":"50-100 mEq","route":"IV","frequency":"Prior to intubation","duration":"Single dose","notes":"Not guideline-endorsed and not routine — the 2024 ADA/EASD consensus considers bicarbonate only if pH <7.0 (superseding the 2009 pH <6.9). Intended to blunt the acidosis worsening from loss of hyperventilation. Give slowly and recheck pH."},"monitoring":"ABG q30min x2h then q1-2h. High MV (12-18 L/min). Minimize PEEP (0-5 cm H2O). Large ETT (>=7.5)."},"summary":"Avoid intubation if possible — loss of hyperventilation worsens acidosis. Use ketamine if unavoidable.","safetyLevel":"critical"}'::jsonb
WHERE id = 'dka-intubation' AND tree_id = 'dka';

-- Node: dka-icu-orders (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":7,"title":"ICU Admission Orders","body":"**ICU-level DKA management:**\n\n**Monitoring:**\n• Continuous cardiac monitor, pulse oximetry, capnography if intubated\n• Arterial line if shock or severe acidosis (pH <6.9)\n• Hourly vitals, UOP q1h, neuro q1h\n• Labs: VBG/ABG q1-2h × 4h, then q2-4h. BMP q2h × 6h then q4h. Lactate q4h. BOHB q4-6h\n\n**Medications:**\n• [Regular insulin IV drip](#/drug/regular-insulin/DKA): 0.1 U/kg/hr (adjust per protocol)\n• [Insulin glargine](#/drug/insulin-glargine/DKA) 0.25-0.3 U/kg SC daily (given on admission)\n• [Potassium chloride or acetate IV](#/drug/potassium-chloride-iv/DKA): 10 mEq/hr IV if K <3.3 (10-20 mEq/hr only via central line with cardiac monitor); once K ≥3.3, 20-30 mEq per LITRE of IV fluid, target K 4-5\n• **Normal saline or balanced crystalloid**: IV bolus then maintenance (or switch to D10W once glucose <300)\n• [Magnesium sulfate](#/drug/magnesium-sulfate/DKA): 1-2 g IV once if Mg <1.5\n• [Thiamine](#/drug/thiamine/DKA): 100 mg IV on admission\n• [Sodium bicarbonate](#/drug/sodium-bicarbonate/DKA) is NOT routine — consider only if pH <7.0 (2024 ADA/EASD): 100 mmol in 400 mL sterile water (isotonic) q2h until pH >7.0\n\n**Consultations:**\n• Endocrinology (mandatory)\n• Nephrology if ESRD/HD or worsening Cr\n• Cardiology if troponin elevated or EKG abnormal\n• Infectious disease if sepsis confirmed\n• Psychiatry if recurrent DKA or suicidal ideation\n\n**Disposition trigger:** When stable (pH >7.25, HCO3 >15, glucose controlled, tolerating PO), stepdown to monitored floor; discharge when all stopping criteria met.","citation":[1,2,5],"recommendation":"ICU admission. Hourly reassessment. Insulin + aggressive electrolyte repletion. Endocrinology, and specialist consultations as indicated. Serial labs q1-4h.","treatment":{"firstLine":{"drug":"Regular insulin IV drip","dose":"0.1 U/kg/hr","route":"IV continuous","frequency":"Continuous, adjust per glucose","duration":"Until DKA resolved","notes":"Reduce to 0.05 U/kg/hr when glucose <250. Never stop for hypoglycemia, give D10W instead."},"alternative":{"drug":"Insulin glargine (basal)","dose":"0.25-0.3 U/kg","route":"Subcutaneous","frequency":"Once daily","duration":"Give on admission, continue at discharge","notes":"Give within 6-12 hrs. Must overlap with IV drip by 2+ hrs before stopping drip."},"monitoring":"Continuous cardiac monitor. VBG/ABG q1-2h x4h then q2-4h. BMP q2h x6h then q4h. K q1-2h. Glucose q1-2h. UOP q1h."},"summary":"ICU orders: insulin drip + glargine, aggressive K+, NS/D10W, thiamine, bicarb only if pH <7.0 (not routine). Labs q1-2h."}'::jsonb
WHERE id = 'dka-icu-orders' AND tree_id = 'dka';

-- Node: dka-floor-orders (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":7,"title":"Monitored Floor Admission Orders","body":"**Moderate DKA on monitored medical floor:**\n\n**Monitoring:**\n• Continuous cardiac monitor + continuous pulse oximetry\n• Vitals q2h, UOP q1h\n• Labs: VBG/ABG q2-4h initially, then q4-6h. BMP q2-4h × 6h then q6h. Lactate q4-6h initially.\n• Neuro checks q2-4h (watch for cerebral edema — rare but catastrophic)\n\n**Medications:**\n• [Regular insulin IV drip](#/drug/regular-insulin/DKA): 0.1 U/kg/hr IV (adjust per glucose response)\n• [Insulin glargine](#/drug/insulin-glargine/DKA) 0.25 U/kg SC daily (given on admission)\n• [Potassium chloride or acetate IV](#/drug/potassium-chloride-iv/DKA): 20-30 mEq per LITRE of IV fluid per K level (target K 4-5; withhold if K >5.0)\n• **Normal saline** then [D10W](#/drug/dextrose/) per \"drop and split\" protocol\n• [Magnesium sulfate](#/drug/magnesium-sulfate/DKA): 1-2 g IV if Mg low\n• [Thiamine](#/drug/thiamine/DKA): 100 mg IV on admission\n\n**Consultations:**\n• Endocrinology (routine, can consult next business day if needed)\n• Case management/social work (address precipitants, discharge planning)\n• Psychiatry if recurrent DKA or mental health concern\n\n**Diet/Activity:**\n• NPO until tolerating PO and glucose <250\n• Once able to eat: start meal-associated insulin (regular or rapid-acting 2-4U with meals)\n• Add sliding scale (2-4 U per 50 mg/dL glucose >150)\n\n**Discharge criteria:**\n• All DKA stopping criteria met (AG <12, HCO3 >18, basal insulin given 2+ hrs ago, glucose <250, tolerating PO)\n• Stable glucose on SC insulin ×2-4 doses\n• Patient education completed\n• Follow-up arranged (endocrinology within 1-2 weeks, PCP within 1 week)\n• Discharge medications and sick-day rules provided","citation":[1,2,5],"recommendation":"Admit to monitored floor. Insulin + electrolyte protocol. Endocrinology and case management consults. Discharge when stopping criteria met + patient stable on SC insulin.","treatment":{"firstLine":{"drug":"Regular insulin IV drip","dose":"0.1 U/kg/hr","route":"IV continuous","frequency":"Continuous","duration":"Until DKA resolved","notes":"Reduce to 0.05 U/kg/hr when glucose <250. Switch to D10W per drop-and-split protocol."},"alternative":{"drug":"Potassium chloride or acetate","dose":"20-30 mEq per LITRE of IV fluid","route":"IV","frequency":"Continuous per K level","duration":"Target K 4-5 mEq/L throughout treatment","notes":"CONCENTRATION in the bag, not an hourly rate. Withhold potassium once K >5.0. Acetate preferred to reduce chloride load."},"monitoring":"Continuous cardiac monitor. VBG q2-4h then q4-6h. BMP q2-4h x6h then q6h. Glucose q1-2h. Neuro q2-4h."},"summary":"Floor orders: insulin drip, glargine, K+ repletion, D10W protocol, labs q2-4h. Discharge when all criteria met."}'::jsonb
WHERE id = 'dka-floor-orders' AND tree_id = 'dka';

-- Node: ed-refeeding (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Refeeding Syndrome","body":"**Refeeding syndrome** is a potentially fatal metabolic response to nutritional rehabilitation after starvation [1][4].\n\n[Refeeding Risk Calculator](#/calculator/refeeding-risk)\n\n**Pathophysiology:**\n- Starvation depletes intracellular phosphate, potassium, magnesium\n- Carbohydrate reintroduction triggers insulin release\n- Insulin drives electrolytes INTO cells\n- Rapid extracellular depletion: arrhythmias, respiratory failure, death\n\n**High Risk Criteria (NICE):**\n- BMI <16 kg/m²\n- >15% weight loss in 3-6 months\n- Minimal nutritional intake >10 days\n- Low K+, Phos, or Mg2+ prior to feeding\n- History of alcohol misuse, cancer, or malabsorption\n\n**Prevention Protocol:**\n1. **Check baseline:** K+, Phos, Mg2+, glucose, ECG\n2. **Correct deficiencies FIRST**\n3. **Start low, go slow:** 10-20 kcal/kg/day initially\n4. **Thiamine 100-200 mg IV** BEFORE feeding (prevents Wernicke)\n5. **Prophylactic phosphate:** 0.3-0.6 mmol/kg/day\n6. **Monitor:** Electrolytes q6-12h for first 72h\n\n**Increase calories by 200 kcal/day** as tolerated over 5-7 days.","citation":[1,4],"next":"ed-risk-strat","treatment":{"firstLine":{"drug":"Thiamine (Vitamin B1)","dose":"100-200 mg","route":"IV","frequency":"Daily x 3-5 days","duration":"Before and during refeeding initiation","notes":"MUST give before carbohydrate loading to prevent Wernicke encephalopathy."},"alternative":{"drug":"Sodium/Potassium Phosphate","dose":"0.3-0.6 mmol/kg/day PO (prophylactic) | 0.2-0.6 mmol/kg IV over 6h by severity (treatment)","route":"IV or PO","frequency":"Daily, divided doses","duration":"Until phosphate stable >2.5 mg/dL","notes":"Start prophylactically with refeeding. IV for Phos <2.0 mg/dL. IV potassium phosphate carries 1.47 mEq potassium per mmol phosphorus — use sodium phosphate if K is 4 mEq/L or higher or renal function is impaired. Do not exceed 45 mmol phosphorus in a single dose."},"monitoring":"Electrolytes q6-12h x 72h, daily weights, strict I/Os, telemetry."},"calculatorLinks":[{"id":"refeeding-risk","label":"Refeeding Risk Calculator"}],"summary":"Refeeding syndrome risk: start low-calorie feeds, monitor phosphate q12h for 72h","safetyLevel":"critical"}'::jsonb
WHERE id = 'ed-refeeding' AND tree_id = 'eating-disorders';

-- Node: ed-electrolyte-replacement (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Electrolyte Replacement Protocol","body":"**Systematic electrolyte correction** before and during refeeding [4].\n\n**Electrolyte Replacement Guide**\n\n**Order of Correction:**\n1. **Magnesium FIRST** (enables K+ repletion)\n2. **Potassium SECOND** (most common deficit)\n3. **Phosphate THIRD** (often normal until refeeding)\n\n**Potassium Replacement:**\n- **K+ 3.0-3.5:** PO KCl 40-80 mEq/day in divided doses\n- **K+ 2.5-3.0:** IV KCl 10 mEq/hr (peripheral) + PO\n- **K+ <2.5:** IV KCl 20 mEq/hr (central line), cardiac monitoring\n\n**Magnesium Replacement:**\n- **Mg2+ 1.5-2.0:** PO Mg oxide 400-800 mg/day\n- **Mg2+ <1.5:** IV MgSO4 2g over 2h, may repeat\n\n**Phosphate Replacement:**\n- **Phos 2.0-2.5:** PO Neutra-Phos 250-500 mg TID\n- **Phos 1.0-2.0:** IV sodium/potassium phos 0.16-0.32 mmol/kg over 6h\n- **Phos <1.0:** IV phos 0.5 mmol/kg over 6h (monitor for hypocalcemia)\n\n**Monitoring:**\n- Q6h electrolytes for first 24-48h of refeeding\n- Daily thereafter until stable\n- ECG daily while QTc elevated","citation":[4],"next":"ed-refeeding-protocol","treatment":{"firstLine":{"drug":"Potassium Chloride","dose":"PO: 40-80 mEq/day divided | IV: 10-20 mEq/hr","route":"PO preferred if K+ >2.5 and tolerating PO","frequency":"Divided doses PO or continuous IV","duration":"Until K+ >3.5 mEq/L","notes":"Max 10 mEq/hr via peripheral IV. Central line for higher rates."},"alternative":{"drug":"Magnesium Sulfate","dose":"2g IV over 2 hours","route":"IV","frequency":"May repeat q4-6h if Mg2+ remains low","duration":"Until Mg2+ >2.0 mEq/L","notes":"Correct before potassium for refractory hypokalemia."},"adjunct":{"drug":"Sodium/Potassium Phosphate","dose":"Prophylactic: 0.3 mmol/kg/day PO | Treatment: 0.2-0.6 mmol/kg IV over 6h by severity","route":"PO (prophylactic) or IV (if Phos <2.0)","frequency":"Daily, check Phos q6h during refeeding","duration":"Until Phos stable >2.5 mg/dL","notes":"Start prophylactically with refeeding. Monitor calcium (can cause hypocalcemia) and do not infuse phosphate through a line carrying calcium. IV potassium phosphate carries 1.47 mEq potassium per mmol phosphorus — use sodium phosphate if K is 4 mEq/L or higher or renal function is impaired."},"monitoring":"Telemetry, electrolytes q6h x 48h then daily, ECG daily while QTc elevated."},"calculatorLinks":[{"id":"electrolyte-replacement","label":"Electrolyte Replacement Guide"}],"summary":"Replace K+ before refeeding, Mg2+ before K+ (Mg depletion causes K+ wasting), check phosphate","safetyLevel":"critical"}'::jsonb
WHERE id = 'ed-electrolyte-replacement' AND tree_id = 'eating-disorders';

-- Node: meth-overdose (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Methadone Toxicity/Overdose","body":"**Signs of methadone toxicity:**\n- Miosis, sedation, slurred speech\n- Respiratory depression (RR < 12)\n- Hypotension\n- QTc prolongation, Torsades de Pointes\n\n**Management:**\n1. Airway support (BVM, intubation if needed)\n2. [Naloxone](#/drug/naloxone/opioid overdose) 0.04-0.4 mg IV titrated to respiratory effort\n3. **Continuous naloxone infusion** often needed: 0.25-0.5 mg/hr\n4. Cardiac monitoring (QTc, arrhythmias)\n5. Correct electrolytes (K+, Mg2+)\n6. **Prolonged observation** - minimum 8-12 hours, often 24+ hours\n\n**Torsades de Pointes:**\n- Magnesium sulfate 2g IV, repeat 2g at 5-15 min if it persists, then a continuous infusion\n- Overdrive pacing or isoproterenol if refractory\n- Discontinue methadone and other QT-prolonging drugs\n\n**Do NOT discharge early** - delayed toxicity common with long half-life.","citation":[13,14],"recommendation":"Methadone toxicity requires prolonged observation (8-24h). Naloxone infusion often needed. Monitor for QTc prolongation and arrhythmias.","treatment":{"firstLine":{"drug":"Naloxone","dose":"0.04-0.4 mg","route":"IV","frequency":"Titrate to respiratory effort","duration":"Followed by infusion 0.25-0.5 mg/hr","notes":"Avoid full reversal (precipitates severe withdrawal). Prolonged infusion often needed."},"monitoring":"Continuous cardiac monitoring. RR, SpO2, sedation level. QTc monitoring. Electrolytes (K+, Mg2+). Observe minimum 8-12 hours."},"confidence":"definitive","summary":"Titrate naloxone to RR not full reversal — continuous infusion often needed, observe 8-24h","safetyLevel":"critical"}'::jsonb
WHERE id = 'meth-overdose' AND tree_id = 'ed-methadone';

-- Node: gb-start (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Biliary Pathology Assessment","body":"[Gallbladder Overview](#/info/gb-overview)\n\n**Key Differentials:**\n• **Biliary colic:** Transient cystic duct obstruction, pain <6h, no fever\n• **Acute cholecystitis:** Persistent obstruction + inflammation, pain >6h, fever\n• **Cholangitis:** CBD obstruction + infection (Charcot''s triad)\n• **Choledocholithiasis:** CBD stone ± symptoms\n\n**Initial Assessment:**\n1. History: pain duration, location, fever, jaundice\n2. Physical exam: Murphy''s sign\n3. Labs: CBC, CMP, LFTs, lipase\n\n**What is the primary concern?**\n\n*Basis:* Differential definitions follow the Tokyo Guidelines 2018 diagnostic criteria for acute cholecystitis [2] and acute cholangitis [9], with narrative review context from JAMA 2022 [1]. These are consensus-based diagnostic criteria (expert panel, international multicentre validation), not outcome trials. The 6-hour pain-duration cutoff separating biliary colic from cholecystitis is a conventional clinical teaching threshold, not a validated decision rule.","citation":[1,2,9],"options":[{"label":"RUQ Pain — Need Workup","next":"gb-exam"},{"label":"Known Cholecystitis — Grade Severity","next":"gb-cholecystitis-grade"},{"label":"Suspected Cholangitis (Fever + Jaundice)","next":"gb-cholangitis-assess"}],"summary":"Biliary colic <6h, no fever; cholecystitis >6h + fever; cholangitis = fever + jaundice + RUQ pain"}'::jsonb
WHERE id = 'gb-start' AND tree_id = 'gallbladder';

-- Node: gb-exam (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Physical Exam & Lab Patterns","body":"[Murphy''s Sign](#/info/gb-murphy)\n\n**Murphy''s Sign:**\n• Technique: Hand on RUQ below costal margin, patient inspires\n• Positive: Inspiratory arrest when hand contacts gallbladder\n• Sensitivity: 75-86%\n• **Specificity: 79-96%** (excellent for ruling IN)\n• **Negative Predictive Value: 90.5%**\n\n**Charcot''s Triad (Cholangitis):**\n• Fever + Jaundice + RUQ pain\n• Present in only 50-70% of cholangitis cases\n• Specificity: 95.9% (if all three present)\n\n**Reynolds'' Pentad (Severe Cholangitis):**\n• Charcot''s triad + Hypotension + Altered mental status\n• Only 4-8% of cholangitis cases\n• Indicates septic shock — emergent drainage needed\n\n**Lab Patterns:**\n\n| Condition | WBC | LFTs | Bilirubin | Lipase |\n|-----------|-----|------|-----------|--------|\n| Biliary colic | Normal | Normal | Normal | Normal |\n| Cholecystitis | ↑ | Normal | Normal | Normal |\n| Cholangitis | ↑ | ↑ ALP | ↑↑ | Normal |\n| Choledocholithiasis | ± | ↑ ALP | ↑ | Normal |\n| Gallstone pancreatitis | ↑ | ↑ | ↑ | ↑↑↑ |\n\n*Basis:* Murphy sign technique and sonographic correlation from Bree [4] and the AFP gallstone review [6]. **Scope limitation — read before relying on these numbers:** the definitive systematic review of the clinical exam in suspected cholecystitis (JAMA Rational Clinical Examination) [15] pooled 17 studies and found the Murphy sign positive likelihood ratio was only 2.8 (95% CI 0.8-8.6, confidence interval crosses 1.0), and concluded that **no single clinical finding or laboratory test is sufficient to establish or exclude acute cholecystitis without imaging**. The specificity range and negative predictive value quoted above come from individual primary studies, not from pooled analysis, and should not be used to rule the diagnosis in or out on their own. Charcot triad specificity derives from the Tokyo Guidelines validation dataset [27], in which the paired reported sensitivity of the triad was 26.4% and specificity 95.6%; the triad frequency figure quoted above comes from older literature and is not the Tokyo-reported value. Reynolds pentad frequency is a descriptive estimate from historical case series with no pooled denominator. Lab-pattern table is a conventional teaching aid [1,2,9], not a validated diagnostic algorithm.","citation":[1,2,3,4,6,9,15,27],"next":"gb-imaging-choice","summary":"Murphy''s sign 79-96% specific; Charcot''s triad 95.9% specific for cholangitis; check LFT pattern"}'::jsonb
WHERE id = 'gb-exam' AND tree_id = 'gallbladder';

-- Node: gb-imaging-choice (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Imaging Selection","body":"[POCUS Gallbladder](#/info/gb-pocus)\n\n**RUQ Ultrasound (First-Line):**\n• Gallstones: Sensitivity >86%, Specificity >88%\n• Overall for cholecystitis: Sens 94%, Spec 84%\n\n**POCUS Findings for Cholecystitis:**\n• Gallstones (echogenic + shadowing)\n• Wall thickening >5mm (90% specific)\n• Pericholecystic fluid\n• Sonographic Murphy''s sign\n\n**When to Get Additional Imaging:**\n\n**CT:** If complications suspected (emphysematous, gangrenous, perforation)\n\n**MRCP:** CBD stones suspected, need to confirm before ERCP\n• Sensitivity 85-100%, Specificity 90%\n\n**HIDA:** Equivocal US, need to confirm cystic duct obstruction\n• 99% specific if gallbladder doesn''t fill\n\n**What do the imaging findings show?**\n\n*Basis:* Ultrasound-first strategy is the Tokyo Guidelines 2018 [2] and WSES 2020 [8] recommendation. **Scope limitation on the accuracy figures above:** the two pooled sources disagree with each other and with the numbers as stated. Shea (meta-analysis, verification-bias adjusted) [17] reported ultrasound for acute cholecystitis at sensitivity 94% / specificity 78% unadjusted and 88% / 80% adjusted, and cholescintigraphy at sensitivity 97% / specificity 90%. Kiewiet (57 studies, 5,859 patients) [16] reported ultrasound sensitivity 81% (95% CI 75-87) and specificity 83% (95% CI 74-89), with cholescintigraphy sensitivity 96% and specificity 90%, and concluded that **the diagnostic accuracy of ultrasound has a substantial margin of error**. Neither pooled source supports a HIDA specificity of 99%. MRCP/EUS performance is from the Cochrane diagnostic test accuracy review [5]. Individual sonographic signs (wall thickening, pericholecystic fluid) have not been validated as standalone criteria; the Tokyo criteria require a combination of local signs, systemic signs, and imaging.","citation":[2,4,5,8,16,17],"options":[{"label":"Gallstones + Positive Sonographic Murphy''s","next":"gb-cholecystitis-grade"},{"label":"Gallstones Only (No Inflammation Signs)","next":"gb-biliary-colic"},{"label":"Dilated CBD (>6mm)","next":"gb-choledocholithiasis"},{"label":"Complications (Gas, Perforation, Abscess)","next":"gb-cholecystitis-severe"}],"summary":"US first-line; POCUS: stones + wall >5mm + sono-Murphy = cholecystitis; MRCP if CBD stone suspected"}'::jsonb
WHERE id = 'gb-imaging-choice' AND tree_id = 'gallbladder';

-- Node: gb-biliary-colic (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Biliary Colic","body":"**Diagnosis:** Transient cystic duct obstruction without inflammation\n\n**Clinical Features:**\n• RUQ/epigastric pain <6 hours duration\n• Pain may radiate to back or right shoulder\n• Often triggered by fatty meal\n• No fever, normal WBC\n• Murphy''s sign may be positive but no peritoneal signs\n\n**Labs:** Normal LFTs, WBC, lipase\n\n**Management:**\n\n**Pain Control:**\n• Ketorolac 15-30mg IV/IM (NSAIDs reduce recurrence)\n• Opioids PRN (morphine, hydromorphone)\n\n**Antiemetics:**\n• Ondansetron 4mg IV\n\n**Disposition:**\n• Discharge with surgical referral\n• Elective cholecystectomy recommended\n• Low-fat diet until surgery\n• Return precautions: fever, worsening pain, jaundice\n\n**Natural History:**\n• 50-70% will have recurrent symptoms\n• 1-3% per year progress to cholecystitis\n\n*Basis:* Diagnosis-by-exclusion of cholecystitis follows the Tokyo Guidelines 2018 criteria [2]; outpatient management and elective cholecystectomy referral follow the AFP gallstone review [6] and JAMA review [1]. NSAID (ketorolac) preference over opioids for biliary colic rests on small randomised analgesia trials summarised in [6]; ketorolac dosing is the standard adult IV/IM range and 15mg is the recommended dose in patients ≥65 years, weight <50kg, or with renal impairment. Recurrence and progression percentages are natural-history estimates from observational cohorts [1,6], not from a single prospective registry.","citation":[1,2,6],"recommendation":"Pain control (ketorolac preferred). Discharge with surgical referral for elective cholecystectomy.","confidence":"recommended","summary":"Biliary colic: pain <6h, no fever, normal labs; ketorolac for pain; discharge with surgical referral"}'::jsonb
WHERE id = 'gb-biliary-colic' AND tree_id = 'gallbladder';

-- Node: gb-cholecystitis-grade (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Tokyo Guidelines — Cholecystitis Severity","body":"[Tokyo Guidelines 2018](#/info/gb-tokyo)\n\n**Grade I (Mild):**\n• Acute cholecystitis without organ dysfunction\n• No severe local inflammation\n• <5% complication rate\n\n**Grade II (Moderate) — ANY of:**\n• WBC >18,000\n• Palpable RUQ mass\n• Symptom duration >72 hours\n• Marked local inflammation:\n  - Gangrenous changes\n  - Pericholecystic abscess\n  - Hepatic abscess\n  - Biliary peritonitis\n  - Emphysematous cholecystitis\n\n**Grade III (Severe) — Organ Dysfunction:**\n• Cardiovascular: vasopressor requirement\n• Neurological: altered mental status\n• Respiratory: PaO2/FiO2 <300\n• Renal: Cr >2.0 or oliguria\n• Hepatic: INR >1.5\n• Hematologic: Platelets <100,000\n\n**What grade?**\n\n*Basis:* Grade I/II/III criteria are reproduced from the Tokyo Guidelines 2018 severity grading for acute cholecystitis [2], endorsed by WSES 2016 [7] and WSES 2020 [8]. This is an international expert-consensus grading system derived from retrospective multicentre cohorts; it stratifies prognosis and guides management intensity but has not been prospectively validated as a treatment-allocation rule in a randomised trial. The organ-dysfunction thresholds (PaO2/FiO2, creatinine, INR, platelets) are the Tokyo definitions and differ from SOFA/qSOFA sepsis criteria — do not use them interchangeably.","citation":[2,7,8],"options":[{"label":"Grade I — Mild","next":"gb-cholecystitis-mild"},{"label":"Grade II — Moderate","next":"gb-cholecystitis-moderate"},{"label":"Grade III — Severe (Organ Dysfunction)","next":"gb-cholecystitis-severe"}],"summary":"Tokyo grading: I = uncomplicated; II = local complications or WBC >18K or >72h; III = organ dysfunction"}'::jsonb
WHERE id = 'gb-cholecystitis-grade' AND tree_id = 'gallbladder';

-- Node: gb-cholecystitis-mild (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Grade I Cholecystitis — Mild","body":"**Management:**\n\n**Antibiotics (Monotherapy):**\n• Piperacillin-tazobactam 4.5g IV q6-8h, OR\n• Ampicillin-sulbactam 3g IV q6h, OR\n• Cefoxitin 2g IV q6h\n\n**Duration:** 3-7 days (can shorten if early cholecystectomy)\n\n**Pain Management:**\n• Ketorolac 15-30mg IV\n• Opioids PRN\n\n**NPO + IV fluids**\n\n**Surgery:**\n• **Early laparoscopic cholecystectomy within 72 hours**\n• Better outcomes than delayed surgery\n• Same-day surgery safe if available\n\n**If Not Surgical Candidate:**\n• Conservative management with antibiotics\n• Percutaneous cholecystostomy if fails antibiotics\n• Interval cholecystectomy 6-8 weeks\n\n*Basis:* Antibiotic agent selection and duration are from the Tokyo Guidelines 2018 antimicrobial therapy chapter [13], cross-checked against the SIS/IDSA complicated intra-abdominal infection guideline [26]; doses shown are standard adult IV doses for normal renal function and require renal adjustment. Early laparoscopic cholecystectomy within 72 hours is supported by the ACDC randomised trial [21] (early vs delayed surgery) and is the WSES 2020 [8] and Tokyo Guidelines 2018 management-flowchart [14] recommendation. Percutaneous cholecystostomy as rescue for antibiotic failure is a consensus recommendation [14], not trial-derived. Evidence quality: surgical timing = randomised trial evidence; antibiotic choice = consensus/observational.","citation":[7,8,13,14,21,26],"recommendation":"Antibiotics (pip-tazo or amp-sulb) + early cholecystectomy within 72h. Pain control with ketorolac.","confidence":"recommended","summary":"Grade I: antibiotics + early lap chole within 72h; pip-tazo or amp-sulb; 3-7 days antibiotics"}'::jsonb
WHERE id = 'gb-cholecystitis-mild' AND tree_id = 'gallbladder';

