INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 10, 'Acute Respiratory Failure Resulting From Lambert-Eaton Myasthenic Syndrome: Case Report and Literature Review. 2024. PMC11144040.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 11, 'Lambert-Eaton myasthenic syndrome during anesthesia: a report of 37 patients (Mayo perioperative series). Anaesthesia. 2014. PMID: 25468580.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 12, 'Respiratory failure in LEMS precipitated by calcium-channel blockers: case report and literature review. 2008. PMID: 19078691.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 13, 'Oh SJ, Kurokawa K, Claussen GC, Ryan HF Jr. Electrophysiological diagnostic criteria of Lambert-Eaton myasthenic syndrome. Muscle Nerve. 2005;32(4):515-520. PMID: 16003742. | Oh SJ. Distinguishing features of the repetitive nerve stimulation test between Lambert-Eaton myasthenic syndrome and myasthenia gravis, 50-year reappraisal. J Clin Neuromuscul Dis. 2017;19(2):66-75. PMID: 29189551. (The 2005 study is the source of the 60% increment threshold: 34 LEMS patients compared against reference values in 40 normal subjects and data from 538 RNS tests in myasthenia gravis, giving 97% sensitivity for LEMS and 99% specificity in excluding MG, versus 85% sensitivity for the older 100% increment "gold standard". The 2017 reappraisal — 34 LEMS vs 140 MG patients — re-confirms the >=60% increment in 97% of LEMS and is the source for low-rate-stimulation decrement being present in only 46% of MG patients.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 14, 'Sabater L, Titulaer M, Saiz A, Verschuuren J, Güre AO, Graus F. SOX1 antibodies are markers of paraneoplastic Lambert-Eaton myasthenic syndrome. Neurology. 2008;70(12):924-928. PMID: 18032743. (SOX1 antibodies were present in 64% of patients with LEMS and SCLC but in none of the 50 patients with idiopathic LEMS, p < 0.0001; series of 105 LEMS patients, 55 with SCLC.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 15, 'Titulaer MJ, Klooster R, Potman M, et al. SOX antibodies in small-cell lung cancer and Lambert-Eaton myasthenic syndrome: frequency and relation with survival. J Clin Oncol. 2009;27(26):4260-4267. PMID: 19667272. (In 86 LEMS patients, 43 with SCLC, SOX antibodies were 67% sensitive and 95% specific for discriminating LEMS with SCLC from non-tumour LEMS. Note the assay measures a SOX1/SOX2/SOX3/SOX21 panel, not SOX1 alone.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 16, 'O''Suilleabhain P, Low PA, Lennon VA. Autonomic dysfunction in the Lambert-Eaton myasthenic syndrome: serologic and clinical correlates. Neurology. 1998;50(1):88-93. PMID: 9443463. (Mayo Clinic series of 30 patients: dry mouth 77% and impotence in 45% of men were the most common symptoms; Composite Autonomic Scoring Scale abnormal in 93%, with severe autonomic failure in 20%. 93% were seropositive for P/Q-type VGCC antibodies versus only 31% for N-type — evidence against a pathogenic role for N-type antibodies.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 17, 'O''Neill JH, Murray NM, Newsom-Davis J. The Lambert-Eaton myasthenic syndrome. A review of 50 cases. Brain. 1988;111(Pt 3):577-596. doi:10.1093/brain/111.3.577. PMID: 2838124. (50 consecutive patients: proximal lower-limb weakness 100%, depressed tendon reflexes 92%, post-tetanic potentiation 78%, dry mouth 74%, mild/moderate ptosis 54%. A patient presenting with LEMS has a 62% risk of underlying SCLC, and that risk declines sharply after 2 years; SCLC was evident within 2 years of LEMS onset in 20 of 21 tumour cases.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 18, 'Wirtz PW, Sotodeh M, Nijnuis M, et al. Difference in distribution of muscle weakness between myasthenia gravis and the Lambert-Eaton myasthenic syndrome. J Neurol Neurosurg Psychiatry. 2002;73(6):766-768. PMID: 12438488. (Direct comparison of 101 myasthenia gravis and 38 LEMS patients: initial weakness was extraocular in 59% of MG patients, whereas no LEMS patient had ocular weakness at onset and 95% had limb-onset weakness, p < 0.001. The authors conclude that if the first symptom is ocular weakness, LEMS is virtually excluded.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('lambert-eaton', 21, 'FIRDAPSE (amifampridine) tablets — FDA-approved prescribing information (Structured Product Label). Catalyst Pharmaceuticals, Inc. Revised 5/2024. DailyMed SPL setid f015fe60-3128-4a43-8c31-19fc6b5def3f. https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f015fe60-3128-4a43-8c31-19fc6b5def3f (Indicated for the treatment of LEMS in adults and pediatric patients 6 years of age and older. Adults and pediatric patients >=45 kg: start 15-30 mg daily in 3 to 5 divided doses, increase total daily dosage by 5 mg every 3 or 4 days, maximum single dose 20 mg, maximum 100 mg/day. Pediatric patients <45 kg: start 5-15 mg daily in 3 to 5 divided doses, increase by 2.5 mg every 3 or 4 days, maximum single dose 10 mg, maximum 50 mg/day. In renal impairment, hepatic impairment and NAT2 poor metabolisers the recommended starting dosage is the lowest recommended initial daily dosage — 15 mg for patients >=45 kg, 5 mg for patients <45 kg.)');

-- Node: mg-torsades (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Torsades / Seizure Mg","body":"[Magnesium Sulfate](#/drug/magnesium-sulfate/Torsades de pointes) 2 g IV over 5-15 min for torsades or unstable polymorphic VT (push over 1-2 min if pulseless/unstable); repeat 2 g at 5-15 min if it persists, then start a continuous infusion - a bolus alone wears off over hours and torsades recurs. Give even if serum magnesium is normal when torsades is present.\n\nCorrect K to high-normal, stop QT-prolonging drugs, treat bradycardia with overdrive pacing/isoproterenol when appropriate, and defibrillate unstable sustained/pulseless rhythms.","citation":[1,5],"next":"mg-hypo-workup","summary":"Torsades: Mg sulfate 2 g IV rapidly, correct K, stop QT drugs, manage bradycardia and defibrillate unstable rhythms.","safetyLevel":"critical"}'::jsonb
WHERE id = 'mg-torsades' AND tree_id = 'magnesium-disorders';

-- Node: palp-exc-torsades (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Torsades de Pointes / Long QT","body":"Open [Torsades de Pointes](#/tree/torsades-de-pointes) for the full pathway.\n\n**Polymorphic VT in the setting of a prolonged QT is torsades de pointes.** It is driven by QT-prolonging drugs and electrolyte depletion (low K, low Mg, low Ca) and can degenerate into VF. [7]\n\n**Put a number on the QT.** The AHA/ACCF action thresholds are a **QTc >500 ms**, or a **rise of ≥60 ms from the pre-drug baseline** — either one demands prompt action (stop/substitute the offending drug, correct electrolytes, defibrillator at the bedside, no off-unit transport). QTc >500 ms carries a **2- to 3-fold** higher torsades risk, and risk climbs continuously (~5-7% per additional 10 ms) rather than switching on at a cutoff. Look for the classic **short-long-short** initiating sequence and QT-U deformity. Beware Bazett over-correction at rates >85 bpm. [7]\n\n**Next 5 minutes:**\n- **Unstable / pulseless → defibrillate** (polymorphic VT is treated with unsynchronized shock; run [Cardiac Arrest](#/tree/cardiac-arrest)).\n- **IV magnesium sulfate 2 g** over minutes is the drug of choice, even if the serum magnesium is normal; repeat as needed.\n- **Correct potassium** (target high-normal) and calcium.\n- **Stop all QT-prolonging drugs.**\n- **Increase the heart rate** to shorten the QT and suppress pauses — overdrive pacing or an isoproterenol infusion for recurrent/pause-dependent torsades (acquired long QT). **Put numbers on it:** overdrive pacing at **90-110 bpm**, or **isoproterenol 1-10 mcg/min titrated to a heart rate of 90-110** — the endpoint is the *rate*, not the drug dose. Correct **potassium to >4.5 mEq/L** while you do it. Both are bridges until the offending drug clears. [4,7]\n- Cardiology/EP consult; admit with continuous monitoring.\n- Distinguish acquired (drugs/electrolytes) from congenital long-QT syndromes (may need beta-blockade, avoid isoproterenol).\n\n🛑 Give magnesium even with a normal level. 🛑 Avoid QT-prolonging antiarrhythmics here — they make it worse; pacing/isoproterenol is the pause-dependent strategy.","citation":[3,4,7,10],"recommendation":"Act at a QTc >500 ms or a ≥60 ms rise from baseline. IV magnesium 2 g (even if level normal) followed by a continuous infusion, correct K to >4.5 mEq/L and Ca, stop QT-prolonging drugs, and raise the rate to 90-110 bpm (overdrive pacing, or isoproterenol 1-10 mcg/min titrated to rate) for recurrent acquired torsades. Defibrillate if pulseless. EP consult + monitored admission.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'palp-exc-torsades' AND tree_id = 'palpitations-hub';

-- Node: pea-hyperK (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Hyperkalemia in Arrest","body":"**Hyperkalemia — membrane stabilization + potassium shifting:**\n\n**1. Calcium (membrane stabilizer):**\n• [Calcium Gluconate](#/drug/calcium-gluconate/hyperkalemia) 1g IV over 2-3 min\n• [Calcium Chloride](#/drug/calcium-chloride/hyperkalemia) 1g IV (central preferred — 3× more elemental Ca²⁺)\n\n**2. Insulin + Dextrose (shift K⁺ intracellular):**\n• Regular insulin IV — dose by hypoglycemia risk\n  - **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  - **10 units** — normal renal function AND adequate glucose\n• D50 50 mL (25 g dextrose) IV with the insulin unless glucose >250 mg/dL\n• Check glucose at 30, 60, 120 and 240 min after the dose\n\n**3. Albuterol (shift K⁺):**\n• 10-20 mg nebulized (continuous)\n\n**4. NaHCO₃ (if acidotic):**\n• 50-100 mEq IV\n\n**Continue high-quality CPR throughout.**","citation":[5,10],"next":"pea-cpr","summary":"Calcium for membrane stabilization, then insulin+D50 and albuterol for K shift, NaHCO3 if acidotic","safetyLevel":"critical"}'::jsonb
WHERE id = 'pea-hyperK' AND tree_id = 'pea-arrest';

-- Node: phos-hypo-severe (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Severe Hypophosphatemia","body":"Use IV phosphate when phos <1 mg/dL, severe symptoms, inability to take PO, respiratory failure, myocardial dysfunction, rhabdomyolysis, hemolysis, or critical illness.\n\nTypical adult IV strategy — dose is elemental phosphorus and is the same for either salt, infused over about 6 hours:\n- Phos 1.7-2.2 mg/dL: 0.2 mmol/kg\n- Phos 1.0-1.7 mg/dL: 0.4 mmol/kg\n- Phos <1.0 mg/dL: 0.6 mmol/kg\nReduce dose by about 50% in renal dysfunction. Do not exceed 45 mmol phosphorus in a single dose.\n\nUse [potassium phosphate](#/drug/potassium-phosphate/Severe hypophosphatemia) only if potassium is low/normal (label threshold: serum K below 4 mEq/L) and renal function allows. It carries a fixed 1.47 mEq of potassium per mmol of phosphorus — 30 mmol P = 44 mEq K, 45 mmol P = 66 mEq K. Count that against every other potassium the patient is receiving.\n\nUse [sodium phosphate](#/drug/sodium-phosphate/Severe hypophosphatemia) when K is high, renal function is impaired, or potassium load is unsafe. It carries 1.33 mEq sodium per mmol phosphorus.\n\nRate for potassium phosphate is limited by the potassium: 6.8 mmol/hr phosphorus peripherally (10 mEq/hr K), 15 mmol/hr centrally (22 mEq/hr K), continuous ECG above 10 mEq/hr K. Do not run phosphate through a line carrying calcium.","citation":[1,2,7,8,9],"next":"phos-monitoring","summary":"IV phosphate for phos <1 or symptomatic; choose NaPhos vs KPhos by potassium and renal function.","safetyLevel":"critical"}'::jsonb
WHERE id = 'phos-hypo-severe' AND tree_id = 'phosphorus-disorders';

-- Node: phos-stop (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"STOP: Phosphate Pitfalls","body":"- Do not give IV phosphate without checking potassium and renal function.\n- Do not use potassium phosphate when hyperkalemic, anuric, or high-risk for potassium accumulation — it delivers a fixed 1.47 mEq of potassium per mmol of phosphorus (30 mmol P = 44 mEq K), and the FDA label restricts it to serum K below 4 mEq/L.\n- Do not run phosphate through a line carrying calcium (lactated Ringer, calcium gluconate), and do not exceed 6.8 mmol/hr peripherally or 15 mmol/hr centrally — rapid infusion causes transient hyperphosphatemia, acute hypocalcemia and precipitation.\n- Do not give repeated IV calcium for asymptomatic hypocalcemia from severe hyperphosphatemia/TLS; treat phosphate and clinical instability.\n- Do not ignore magnesium; phosphate depletion and phosphate replacement can both worsen Mg problems.\n- Do not discharge severe, symptomatic, recurrent, renal-failure, TLS, rhabdo, DKA, or refeeding-risk phosphate disorders without a monitoring plan.","citation":[1,2,3,5],"recommendation":"Phosphate therapy is paired-electrolyte therapy: recheck Ca/Mg/K/Cr and treat the driver.","confidence":"recommended"}'::jsonb
WHERE id = 'phos-stop' AND tree_id = 'phosphorus-disorders';

