-- Node: kclinf-dka (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"DKA / HHS Potassium Rules","body":"Potassium determines whether insulin can safely start.\n\nDKA/HHS rules:\n- K <3.3 mEq/L: hold insulin; give [Potassium chloride IV](#/drug/potassium-chloride-iv/DKA severe hypokalemia) 10 mEq/hr until K >=3.3 (10-20 mEq/hr only with central access + continuous cardiac monitoring)\n- K 3.3-5.2 mEq/L: give 20-30 mEq potassium per LITRE of IV fluid while insulin runs — a concentration in the bag, not an hourly rate\n- K >5.2 mEq/L: do not give potassium initially; recheck q2h and start replacement when K falls into range\n\nUse a mix of potassium chloride, [potassium phosphate](#/drug/potassium-phosphate/DKA phosphate repletion), and [potassium acetate](#/drug/potassium-acetate/DKA) when phosphate deficit or hyperchloremia is relevant per protocol. Potassium phosphate delivers 1.47 mEq potassium per mmol of phosphorus — count it in the hourly potassium total.","citation":[4,5],"next":"kclinf-monitor","summary":"In DKA/HHS, hold insulin when K <3.3 and replace before insulin.","safetyLevel":"critical"}'::jsonb
WHERE id = 'kclinf-dka' AND tree_id = 'potassium-infusion';

-- Node: k-hyper-insulin (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Insulin + Dextrose — K+ Shift","body":"**[Regular Insulin](#/drug/regular-insulin) IV — dose by hypoglycemia risk** (must be IV, NOT subcutaneous). Give WITH **25 g dextrose (D50W 50 mL)** unless glucose >250 mg/dL.\n\n• **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n• **10 units** — normal renal function AND adequate glucose\n\n**Check glucose at 30, 60, 120 and 240 minutes.** If glucose < 70 → give additional dextrose.\n\n**Dextrose delivery:** D50W 50 mL (25 g) IV is the standard co-administration. **D10W 500 mL over 4 hours** is an acceptable alternative with less rebound hypoglycemia. Glucose > 250 mg/dL → no dextrose needed.\n\n**Effect:** Onset 15-30 min. K+ reduction: 0.5-1.2 mEq/L. Duration: ~4 hours — plan for redosing or definitive therapy.","citation":[1,3,4],"next":"k-hyper-beta2","treatment":{"firstLine":{"drug":"Regular Insulin + Dextrose","dose":"5 units (10 units if normal renal function AND adequate glucose) + 25 g dextrose (D50W 50 mL)","route":"IV bolus (both) - insulin must be IV, NOT subcutaneous","frequency":"Once, may redose in 4 hours","duration":"4 hours effect","notes":"Use 5 units (or 0.1 units/kg, max 10) if eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes. Skip dextrose if glucose >250."},"alternative":{"drug":"Regular Insulin + D10W infusion","dose":"5 units (10 units if normal renal function AND adequate glucose) + D10W 500 mL over 4 hours","route":"IV bolus (insulin) + IV infusion (D10W)","frequency":"Once, may redose in 4 hours","duration":"4 hours effect","notes":"Prolonged dextrose delivery - less rebound hypoglycemia than a single D50W bolus. Skip dextrose if glucose >250."},"monitoring":"Fingerstick glucose at 30, 60, 120 and 240 minutes. Give additional dextrose if glucose <70."},"summary":"Insulin 5 units IV (10 units if normal renal function AND adequate glucose) + 25 g dextrose — glucose at 30/60/120/240 min, K+ drops 0.5-1.2","safetyLevel":"warning"}'::jsonb
WHERE id = 'k-hyper-insulin' AND tree_id = 'potassium';

