INSERT INTO tree_citations (tree_id, num, text) VALUES ('proximal-weakness-hub', 15, 'Kodadek L, Carmichael SP 2nd, Seshadri A, Pathak A, Hoth J, Appelbaum R, Michetti CP, Gonzalez RP. Rhabdomyolysis: an American Association for the Surgery of Trauma Critical Care Committee Clinical Consensus Document. Trauma Surg Acute Care Open. 2022;7(1):e000836. PMID: 35136842. PMCID: PMC8804685. doi:10.1136/tsaco-2021-000836. Bosch X, Poch E, Grau JM. Rhabdomyolysis and acute kidney injury. N Engl J Med. 2009;361(1):62-72. PMID: 19571284. doi:10.1056/NEJMra0801327. Scharman EJ, Troutman WG. Prevention of kidney injury following rhabdomyolysis: a systematic review. Ann Pharmacother. 2013;47(1):90-105. PMID: 23324509. doi:10.1345/aph.1R215. Brown CV, Rhee P, Chan L, Evans K, Demetriades D, Velmahos GC. Preventing renal failure in patients with rhabdomyolysis: do bicarbonate and mannitol make a difference? J Trauma. 2004;56(6):1191-1196. PMID: 15211124. doi:10.1097/01.ta.0000130761.78627.10. (Primary source for "bicarbonate/mannitol are not routine": 2,083 trauma ICU admissions; among those with CK >5,000 U/L there was no difference in renal failure, dialysis or mortality with bicarbonate/mannitol.) Long B, Koyfman A, Gottlieb M. An evidence-based narrative review of the emergency department evaluation and management of rhabdomyolysis. Am J Emerg Med. 2019;37(3):518-523. PMID: 30630682. doi:10.1016/j.ajem.2018.12.061. (ED-scoped source for the CK >5x ULN diagnostic threshold and for the statement that bicarbonate, mannitol and loop diuretics lack strong outcome evidence. NOTE: Long et al. state a goal urine output of 300 mL/h; the 1-3 mL/kg/h target used on this node is the weight-indexed equivalent commonly quoted in the critical-care literature.)');
