-- Node: psych-start (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Psychiatric Assessment — Overview","body":"A **comprehensive psychiatric assessment** follows a structured format including both historical information and a systematic **Mental Status Examination (MSE)**.\n\nThe MSE is a structured way to assess and document a patient''s current cognitive, behavioral, and emotional functioning. Unlike the MMSE (cognitive screening), the MSE offers a **broader view** of the patient''s psychological state during a specific encounter.\n\n**10 Components of the MSE:**\n1. Appearance\n2. Behavior\n3. Speech & Language\n4. Mood (subjective)\n5. Affect (objective)\n6. Thought Process\n7. Thought Content & Perception\n8. Suicidal / Homicidal Risk\n9. Cognition\n10. Insight & Judgment\n\n**Documentation for CPT 90792 must include:**\n• Complete medical and psychiatric history\n• Mental status examination findings\n• Initial diagnosis\n• Evaluation of capacity to respond to treatment\n• Initial treatment plan\n\n*Basis:* The 10-component MSE structure and the MSE-vs-MMSE distinction are drawn from narrative reviews of MSE technique in Am Fam Physician [1][2][6] and from non-peer-reviewed educational templates [9] — see the citation list for evidence-quality notes on [9]. The MSE itself is a **descriptive documentation framework, not a validated diagnostic instrument**: no MSE component has a published sensitivity, specificity, or likelihood ratio for any diagnosis, and findings must be interpreted with history, vital signs, and physical examination. The CPT 90792 documentation elements are a billing requirement defined by the AMA CPT code set [25], not a clinical evidence statement.","citation":[1,2,6,9,25],"next":"psych-history","summary":"10-component MSE: appearance through insight/judgment — CPT 90792 requires full MSE + treatment plan","skippable":true}'::jsonb
WHERE id = 'psych-start' AND tree_id = 'psych-assessment';

