INSERT INTO tree_citations (tree_id, num, text) VALUES ('psych-assessment', 22, 'Duty to warn / protect authorities: Tarasoff v. Regents of the University of California, 17 Cal.3d 425, 551 P.2d 334 (Cal. 1976); Thapar v. Zezulka, 994 S.W.2d 635 (Tex. 1999) (Supreme Court of Texas, decided 24 June 1999, Enoch J., declined to recognise a common-law duty to warn because the Texas mental-health confidentiality statute makes such a duty unwise); National Conference of State Legislatures, Mental Health Professionals'' Duty to Warn, https://www.ncsl.org/health/mental-health-professionals-duty-to-warn (last substantively updated 2022). No PMID/DOI (case law and legislative tracking). CURRENCY WARNING: state duty-to-warn statutes change frequently, particularly regarding firearms access. Verify the current statute in your jurisdiction before relying on any state classification.');
