-- Node: rvf-hyperK (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Hyperkalemia Treatment Stack","body":"**During cardiac arrest:**\n\n1. **[Calcium chloride](#/drug/calcium-chloride/hyperK)** 1g IV (or Calcium gluconate 3g IV) — membrane stabilization\n2. **[Regular insulin](#/drug/regular-insulin/hyperK)** + **D50** 50 mL (25 g dextrose) IV unless glucose >250 mg/dL — intracellular shift\n  - **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  - **10 units** — normal renal function AND adequate glucose\n  - Check glucose at 30, 60, 120 and 240 min after the dose\n3. **[Albuterol](#/drug/albuterol-neb/hyperK)** 10-20 mg nebulized — intracellular shift\n4. **[Sodium bicarbonate](#/drug/sodium-bicarbonate/hyperK)** 50-100 mEq IV if acidotic\n5. **Dialysis** if refractory\n\n**Continue ACLS** while treating hyperkalemia [2]","citation":[2],"next":"rvf-vector-change","treatment":{"firstLine":{"drug":"Calcium chloride","dose":"1g (10 mL of 10%) IV","route":"IV push","frequency":"Once","duration":"Single dose","notes":"Membrane stabilization. Alternative: Calcium gluconate 3g IV."},"alternative":{"drug":"Insulin + D50","dose":"Regular insulin 5 units (10 units if normal renal function) + D50 50 mL (25 g dextrose)","route":"IV","frequency":"Once","duration":"Single dose","notes":"Intracellular K shift. Add albuterol 10-20 mg neb."},"monitoring":"Continue ACLS, check K when ROSC. Check glucose at 30, 60, 120 and 240 min after insulin."},"summary":"Calcium chloride 1g IV for membrane stabilization, then insulin/D50 and albuterol for K shift","safetyLevel":"critical"}'::jsonb
WHERE id = 'rvf-hyperK' AND tree_id = 'refractory-vfvt';

-- Node: rvf-other-agents (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Other Pharmacologic Options","body":"**Magnesium Sulfate:**\n• **Torsades de Pointes:** [Magnesium](#/drug/magnesium-sulfate/torsades) 2g IV over 2 min, repeat 2g at 5-15 min if it persists, then a continuous infusion\n• **Routine refractory VF:** NOT recommended [2]\n\n**Sodium Bicarbonate:**\n• Severe acidosis (pH <7.2): 1 mEq/kg IV\n• Hyperkalemia: 50-100 mEq IV\n• TCA overdose: 1-2 mEq/kg IV\n• **Routine use:** NOT recommended [2]\n\n**Procainamide:**\n• 20 mg/min up to 17 mg/kg\n• Used for stable VT, uncertain in arrest","citation":[2],"next":"rvf-esmolol-consider","summary":"MgSO4 only for torsades, NaHCO3 only for acidosis/hyperK/TCA — neither for routine refractory VF"}'::jsonb
WHERE id = 'rvf-other-agents' AND tree_id = 'refractory-vfvt';

-- Node: rhabdo-hyperkalemia-tx (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Hyperkalemia Management","body":"**Life-threatening hyperkalemia requires immediate treatment:**\n\n**Cardiac membrane stabilization:**\n• [Calcium gluconate](#/drug/calcium-gluconate/hyperkalemia) 1-2 g IV over 2-3 min (preferred) OR\n• [Calcium chloride](#/drug/calcium-chloride/hyperkalemia) 500-1000 mg IV (central line preferred)\n\n**Potassium shifting:**\n• [Regular insulin](#/drug/regular-insulin/hyperkalemia) IV — dose by hypoglycemia risk. Give WITH 25 g dextrose ([D50W](#/drug/dextrose/hyperkalemia) 50 mL) unless glucose >250 mg/dL\n  — **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  — **10 units** — normal renal function AND adequate glucose\n  — Rhabdomyolysis-associated AKI puts most patients in the 5-unit group\n  — Check glucose at 30, 60, 120 and 240 min\n• [Albuterol](#/drug/albuterol-neb/hyperkalemia) 10-20 mg nebulized\n• [Sodium bicarbonate](#/drug/sodium-bicarbonate/hyperkalemia) 50-100 mEq IV (if acidotic)\n\n**Potassium elimination:**\n• [Furosemide](#/drug/furosemide/hyperkalemia) 40-80 mg IV (if adequate urine output)\n• Dialysis for refractory cases or AKI\n\n**Continuous cardiac monitoring. Recheck K in 1-2 hours.**\n\nSee [Potassium Disorders](#/tree/potassium) for complete management.","citation":[1,6],"recommendation":"Treat hyperkalemia immediately with calcium, insulin/glucose, albuterol. Consider dialysis if refractory or anuric.","treatment":{"firstLine":{"drug":"Calcium gluconate","dose":"1-2 g (10-20 mL of 10%)","route":"IV","frequency":"Over 2-3 min, may repeat","duration":"As needed for cardiac protection","notes":"Cardiac membrane stabilization. Does NOT lower K."},"alternative":{"drug":"Regular insulin + D50W","dose":"Insulin 5 units IV (10 units if normal renal function and adequate glucose) + 25 g dextrose (D50W 50 mL)","route":"IV","frequency":"Once, may repeat","duration":"Effect lasts 4-6 hours","notes":"Shifts K intracellularly. Dose by hypoglycemia risk — 5 units (or 0.1 units/kg, max 10) if eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes (LaRue 2017; Moussavi 2021); 10 units if normal renal function AND adequate glucose (Pierce 2020; UKKA 2023). Check glucose at 30, 60, 120 and 240 min."},"monitoring":"Continuous cardiac monitor. Recheck K in 1-2 hours. Glucose at 30, 60, 120 and 240 min after insulin."},"confidence":"definitive"}'::jsonb
WHERE id = 'rhabdo-hyperkalemia-tx' AND tree_id = 'rhabdomyolysis';

-- Node: st-start (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Severe Sore Throat Hub — Is the Airway Threatened?","body":"**⚠️ 5 DO NOT MISS:**\n1. **Epiglottitis / supraglottitis** — rapid airway obstruction; sitting-forward, drooling, muffled voice, stridor. Do NOT lie the patient down or examine the throat aggressively.\n2. **Ludwig angina** — bilateral submandibular swelling, tongue elevation, floor-of-mouth induration; airway emergency.\n3. **Retropharyngeal / deep-neck abscess** — neck stiffness, fever, dysphagia; can descend to mediastinitis.\n4. **Peritonsillar abscess** — unilateral, trismus, uvular deviation, “hot potato” voice.\n5. **Non-throat killers presenting as sore throat** — angioedema, caustic/foreign-body ingestion, post-tonsillectomy bleed, MI/ACS referred pain.\n\n**First 60 seconds — the airway question:** the sore throat that kills is the one obstructing the airway. Screen for the red flags of impending obstruction BEFORE anything else. [1,2]\n\n**Airway red flags (any of these = airway emergency, get help early):**\n- **Stridor** or noisy breathing\n- **Drooling / cannot handle secretions**\n- **Tripod / sitting-forward, refusing to lie flat**\n- **Muffled “hot potato” voice**\n- **Trismus** (cannot open mouth)\n- **Tongue elevation / floor-of-mouth swelling** (Ludwig)\n- **Rapidly progressive neck swelling**, subcutaneous crepitus\n\n**If any airway red flag:** minimal-stimulation approach, sit the patient up, high-flow oxygen, call ENT + anesthesia for a difficult-airway/double-setup EARLY, prepare for an awake fiberoptic approach and a surgical airway backup. Do NOT force a tongue-blade throat exam or lay an epiglottitis patient flat. See [Awake Intubation](#/tree/awake-intubation) and [Cricothyrotomy](#/tree/cricothyrotomy) for the difficult-airway pathways.\n\n**Scan in 30 seconds:** [1]\n- Airway red flags above; work of breathing; SpO2; voice quality\n- Vitals — fever, tachycardia, sepsis physiology\n- Neck — swelling (unilateral vs bilateral), crepitus, tender adenopathy, meningismus\n- Mouth (gentle) — uvular deviation, tonsillar exudate, floor-of-mouth induration, lesions\n- Drooling, trismus, ability to swallow saliva\n\n**The 4 questions that change the differential:** [1,2]\n1. **Any airway red flag (stridor, drooling, tripod, muffled voice, trismus)?** (airway emergency — ENT/anesthesia now)\n2. **Unilateral throat + trismus + deviated uvula?** (peritonsillar abscess)\n3. **Sudden tongue/lip/throat swelling ± ACE inhibitor / allergen?** (angioedema)\n4. **Ingestion (caustic, foreign body, button battery) or recent tonsillectomy?** (redirect to that pathway)\n\n---\n\n*Basis:* the airway red-flag list, the minimal-stimulation rule and the 30-second scan in this node are **consensus criteria** compiled from emergency-medicine reviews of the sore throat presentation and oropharyngeal infection [1,10] and a deep neck space infection review [2]. **They are not a validated decision rule.** No prospectively validated instrument exists to predict which sore throat patient will obstruct, so the red flags should be read as findings that mandate early airway expertise — not as a scored triage tool with a published sensitivity. The direction to involve ENT and anaesthesia before the patient deteriorates reflects reported airway-loss events in observational series rather than trial evidence.","citation":[1,2,10],"next":"st-exclusions","summary":"Screen for airway red flags FIRST (stridor, drooling, tripod, muffled voice, trismus, tongue elevation). If present: sit up, minimal stimulation, ENT + anesthesia early, do not force a throat exam or lie the patient flat.","safetyLevel":"critical"}'::jsonb
WHERE id = 'st-start' AND tree_id = 'sore-throat-hub';

-- Node: st-exclusions (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Time-Critical Exclusions — Pick the One That Fits","body":"Airway threats first. Each branch routes to a deep-dive (or an airway plan) and the next action.\n\n---\n\n*Basis:* this is a **routing node** — each branch label is a recognition pattern, not a treatment recommendation, and the evidence for what to do sits in the destination node and its linked consult. The branch set and the airway-first ordering derive from emergency-medicine reviews of the sore throat presentation and of oropharyngeal and neck-space infection [1,2,10]; the non-emergent branch routes to pharyngitis assessment governed by the IDSA guideline [3]. The ordering is consensus, not a validated triage sequence.","citation":[1,2,3,10],"options":[{"label":"Stridor, drooling, tripod posture, muffled voice — impending obstruction","description":"Epiglottitis / supraglottitis — minimal stimulation, ENT + anesthesia NOW","next":"st-exc-epiglottitis","urgency":"critical"},{"label":"Bilateral submandibular swelling, tongue elevation, floor-of-mouth induration","description":"Ludwig angina — airway emergency, ENT/OMFS + anesthesia, antibiotics","next":"st-exc-ludwig","urgency":"critical"},{"label":"Fever + neck stiffness / pain + dysphagia, ill-appearing","description":"Deep neck / retropharyngeal abscess — CT neck, ENT, IV antibiotics","next":"st-exc-deepneck","urgency":"critical"},{"label":"Sudden lip/tongue/throat swelling ± ACE inhibitor or allergen","description":"Angioedema — airway watch, treat allergic vs bradykinin-mediated","next":"st-exc-angioedema","urgency":"critical"},{"label":"Unilateral throat pain + trismus + uvular deviation + hot-potato voice","description":"Peritonsillar abscess — drainage + antibiotics","next":"st-exc-pta","urgency":"urgent"},{"label":"Caustic, foreign body, or button-battery ingestion; or recent tonsillectomy","description":"Redirect to the ingestion / post-tonsillectomy pathway","next":"st-exc-ingestion","urgency":"urgent"},{"label":"None of the above — sore throat without airway threat, stable","description":"Initial bundle + pharyngitis workup","next":"st-rescue"}],"summary":"Airway threats first (epiglottitis, Ludwig, deep-neck, angioedema), then PTA, then redirect ingestions. Each branch links to its deep-dive or airway plan.","safetyLevel":"critical"}'::jsonb
WHERE id = 'st-exclusions' AND tree_id = 'sore-throat-hub';

-- Node: st-exc-epiglottitis (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Epiglottitis / Supraglottitis — Airway Emergency","body":"**(No dedicated consult yet — airway pathways linked below.)** Adult epiglottitis is easy to miss because the throat can look unremarkable; the tip-off is severe odynophagia/dysphagia out of proportion to the visible exam, plus a muffled voice, drooling, and a preference to sit forward. Progression to complete obstruction can be sudden. [4]\n\n**The cardinal rule: minimize stimulation.** Do NOT force a tongue-blade exam, do NOT lay the patient flat, do NOT agitate a child — any of these can precipitate complete obstruction.\n\n**Next 5 minutes:**\n- **Sit the patient up, high-flow humidified oxygen, keep them calm** (especially children — let a parent hold them).\n- **Call ENT + anesthesia immediately for a difficult-airway / double-setup** in the OR when feasible — awake fiberoptic intubation with surgical-airway backup. See [Awake Intubation](#/tree/awake-intubation) and [Cricothyrotomy](#/tree/cricothyrotomy).\n- **Do NOT attempt routine RSI** in a threatened epiglottic airway without the difficult-airway team and a surgical-airway plan ready.\n- IV access (without agitating the patient), monitor.\n- **IV antibiotics** covering H. influenzae, Strep, and Staph: ceftriaxone (± vancomycin if MRSA risk); add coverage per local patterns.\n- Consider IV steroids (dexamethasone) for airway edema (adjunct, not a substitute for airway readiness).\n- Lateral soft-tissue neck X-ray (“thumbprint sign”) only if the patient is stable and it will not delay definitive airway management — do not send an unstable airway to radiology.\n\n🛑 Do NOT examine the throat with a tongue blade or lie the patient flat. 🛑 The safest place to secure this airway is a controlled setting (OR) with ENT/anesthesia — involve them BEFORE the patient crashes.\n\n---\n\n*Basis:* the minimal-stimulation rule, the preference for a controlled/awake airway and the surgical-airway backup requirement derive from peer-reviewed emergency-medicine reviews of adult epiglottitis [12,13] and from a systematic review and meta-analysis of airway management in adult epiglottitis [14]; the StatPearls chapter [4] supplies descriptive and epidemiologic background only. **Evidence quality across this node is low.** There are no randomised trials in epiglottitis — every recommendation here is derived from observational cohorts, case series and pooled retrospective data, and represents a consensus airway-safety pathway rather than a trial-derived protocol. Antibiotic selection is empiric, class-based coverage of *H. influenzae*, streptococci and staphylococci, with an anti-MRSA agent added by local risk; the agents named are used per FDA-approved labelling [26] and **no trial establishes a preferred regimen.** **Corticosteroids in adult epiglottitis are supported only by observational data and expert opinion [13,14]** — consistent with the framing above, they are an adjunct and do not alter the need for airway readiness. Lateral neck radiography has limited sensitivity and a normal film does not exclude the diagnosis [13].","citation":[4,12,13,14,26],"recommendation":"Minimal stimulation, sit up, oxygen, keep calm. ENT + anesthesia NOW for a controlled/awake airway with surgical backup. IV antibiotics (ceftriaxone ± vancomycin) + steroids. Do not force a throat exam or lie the patient flat.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'st-exc-epiglottitis' AND tree_id = 'sore-throat-hub';

-- Node: st-exc-ludwig (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Ludwig Angina — Floor-of-Mouth Airway Threat","body":"**(No dedicated consult yet — airway + antibiotic pathway below.)** Ludwig angina is a rapidly spreading bilateral cellulitis of the submandibular/sublingual spaces, usually from a dental source. It elevates and displaces the tongue posteriorly and threatens the airway. [5]\n\n**Recognize:** bilateral submandibular swelling and induration, elevated/protruding tongue, floor-of-mouth swelling, drooling, trismus, “hot potato” voice, fever, ill appearance. The airway can obstruct quickly.\n\n**Next 5 minutes:**\n- **Sit the patient up, oxygen, keep calm; call ENT/OMFS + anesthesia early** for a controlled airway (awake fiberoptic; surgical airway backup) — see [Awake Intubation](#/tree/awake-intubation) and [Cricothyrotomy](#/tree/cricothyrotomy).\n- Do NOT rely on oral intubation — tongue displacement makes it difficult; plan a difficult airway.\n- **IV broad-spectrum antibiotics** covering oral flora (aerobes + anaerobes): ampicillin-sulbactam or piperacillin-tazobactam; add vancomycin/clindamycin if MRSA risk; high-dose per local guidance.\n- IV steroids (dexamethasone) as an adjunct for edema.\n- **CT neck with contrast** once the airway is secured/stable to define the extent and any drainable collection or descending spread.\n- ENT/OMFS for source control (dental extraction, drainage) and admission.\n\n🛑 The airway is the priority — secure it in a controlled setting before it is lost. 🛑 Do not send an unstable airway to CT.\n\n---\n\n*Basis:* the recognition features, the early-controlled-airway rule, the warning against relying on oral intubation, and the antibiotic classes named in this node derive from an evidence-based emergency-medicine review of Ludwig angina [5] and an emergency-medicine review of neck-space infections [11]; the named parenteral agents are used per FDA-approved labelling [26]. **Evidence quality is low — the base is entirely observational** (case series and narrative review). **There are no randomised trials of airway strategy, corticosteroid use or antibiotic regimen in Ludwig angina**, and the direction to secure the airway early reflects consensus derived from reported airway-loss events rather than comparative data. Source control and CT timing likewise reflect expert consensus.","citation":[5,11,26],"recommendation":"Sit up + oxygen + calm; ENT/OMFS + anesthesia early for a controlled/awake airway with surgical backup. IV broad-spectrum antibiotics + steroids. CT neck once stable. Source control and admission.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'st-exc-ludwig' AND tree_id = 'sore-throat-hub';

-- Node: st-exc-deepneck (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Deep Neck / Retropharyngeal Abscess","body":"Open [Deep Neck Infection](#/tree/deep-neck-infection) for the full imaging, antibiotic, and drainage pathway.\n\n**Retropharyngeal and other deep-neck-space abscesses** present with fever, severe sore throat, odynophagia, neck stiffness/pain, and an ill appearance; retropharyngeal abscess classically causes neck extension posturing and can descend into the mediastinum (mediastinitis) — a life-threatening complication. [6]\n\n**Next 5 minutes:**\n- Airway assessment first (any red flag → treat as an airway emergency, ENT + anesthesia).\n- **CT neck with IV contrast** is the key diagnostic test — localizes the space, differentiates cellulitis/phlegmon from a drainable abscess, and shows mediastinal extension.\n- **IV broad-spectrum antibiotics** covering aerobes + anaerobes (ampicillin-sulbactam or piperacillin-tazobactam; add vancomycin/clindamycin for MRSA/severe).\n- IV fluids, analgesia, blood cultures if septic.\n- **ENT consult** for drainage; watch for descending mediastinitis (chest pain, widened mediastinum, sepsis) → thoracic surgery.\n- Admit.\n\n🛑 Do not miss descending mediastinitis — a deep-neck infection with chest pain / sepsis needs chest imaging and surgical involvement. 🛑 Secure the airway before CT if there are red flags.\n\n---\n\n*Basis:* CT neck with IV contrast as the diagnostic test of choice, the aerobe-plus-anaerobe empiric antibiotic strategy, and the descending-mediastinitis warning derive from otolaryngology and emergency-medicine reviews of deep neck space infection [2,11,12] and the pharyngitis-mimics review [6]; the named parenteral agents are used per FDA-approved labelling [26]. **Evidence is observational** — retrospective cohorts, case series and narrative review. **No randomised trial compares imaging strategies, antibiotic regimens or drainage timing in deep neck infection**, and the abscess-versus-phlegmon distinction on CT is imperfect. Full imaging, antibiotic and drainage detail is owned by the linked Deep Neck Infection consult, which is the governing source for this branch.","citation":[6],"recommendation":"CT neck with contrast to localize and find drainable collection/mediastinal spread. IV broad-spectrum antibiotics + fluids. ENT for drainage; watch for descending mediastinitis. Airway first if red flags. Admit.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'st-exc-deepneck' AND tree_id = 'sore-throat-hub';

