DELETE FROM tree_citations WHERE tree_id = 'sore-throat-hub';
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 1, 'Klein MR. Infections of the Oropharynx. Emerg Med Clin North Am. 2019;37(1):69-80. doi:10.1016/j.emc.2018.09.002. PMID: 30454781. (Replaces a prior entry in this slot — "Somro A, et al. Acute sore throat: assessment and management in the emergency department. Emerg Med Clin North Am. 2019;37(1):73-85" — which does not exist: no such author, title or page range in that journal. This is the real same-issue, same-topic article. Scope: oropharyngeal infection recognition; does not cover angioedema, ingestions or disposition rules.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 2, 'Vieira F, Allen SM, Stocks RM, Thompson JW. Deep neck infection. Otolaryngol Clin North Am. 2008;41(3):459-483, vii. doi:10.1016/j.otc.2008.01.002. PMID: 18435993. (Scope: deep neck space anatomy, imaging and drainage. Narrative otolaryngology review; it does not address angioedema, pharyngitis testing or ED discharge criteria — those claims are sourced separately below.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 3, 'Shulman ST, Bisno AL, Clegg HW, et al. Clinical practice guideline for the diagnosis and management of group A streptococcal pharyngitis: 2012 update by the Infectious Diseases Society of America. Clin Infect Dis. 2012;55(10):1279-1282. doi:10.1093/cid/cis847. PMID: 23091044. (This is the abridged guideline; the full-text version is Clin Infect Dis. 2012;55(10):e86-e102, doi:10.1093/cid/cis629, PMID: 22965026. Source of the GAS testing thresholds and antibiotic regimens referenced from this hub. The 2025 IDSA update (PMID: 41343363) revises risk assessment and clinical scoring ONLY — treatment recommendations still derive from this 2012 document.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 4, 'Sutton AE, Waseem M. Epiglottitis. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026 Jan-. NCBI Bookshelf ID: NBK430960. PMID: 28613691. https://www.ncbi.nlm.nih.gov/books/NBK430960/ (Author string corrected — this chapter was previously cited here as "Guerra AM, Waseem M"; the NLM Bookshelf record lists Sutton AE and Waseem M. Scope: descriptive and epidemiologic background. Non-peer-reviewed point-of-care reference; the airway-management recommendations in this hub are sourced to the peer-reviewed reviews at [13] and [14].)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 5, 'Bridwell R, Gottlieb M, Koyfman A, Long B. Diagnosis and management of Ludwig’s angina: An evidence-based review. Am J Emerg Med. 2021;41:1-5. doi:10.1016/j.ajem.2020.12.030. PMID: 33383265.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 6, 'Gottlieb M, Long B, Koyfman A. Clinical Mimics: An Emergency Medicine-Focused Review of Streptococcal Pharyngitis Mimics. J Emerg Med. 2018;54(5):619-629. doi:10.1016/j.jemermed.2018.01.031. PMID: 29523424. (Title and page range corrected — previously cited here as "Clinical Mimics: An Emergency Medicine-Focused Review of Deep Neck Infections. J Emerg Med. 2018;54(5):683-692", which is not a real article; no "Deep Neck Infections" entry exists in the Clinical Mimics series and pages 683-692 of that issue are unrelated papers. The real article does cover the deep neck space and airway mimics of streptococcal pharyngitis, which is the use made of it here.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 7, 'Long BJ, Koyfman A, Gottlieb M. Evaluation and Management of Angioedema in the Emergency Department. West J Emerg Med. 2019;20(4):587-600. doi:10.5811/westjem.2019.5.42650. PMID: 31316698.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 8, 'Galioto NJ. Peritonsillar Abscess. Am Fam Physician. 2017;95(8):501-506. PMID: 28409615. (No DOI assigned by the publisher; PMID is the machine identifier.) https://pubmed.ncbi.nlm.nih.gov/28409615/');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 9, 'Sykes EA, Wu V, Beyea MM, Simpson MTW, Beyea JA. Pharyngitis: Approach to diagnosis and treatment. Can Fam Physician. 2020;66(4):251-257. PMID: 32273409. (No DOI assigned by the publisher; PMID is the machine identifier.) https://pubmed.ncbi.nlm.nih.gov/32273409/');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 10, 'Cirilli AR. Emergency evaluation and management of the sore throat. Emerg Med Clin North Am. 2013;31(2):501-515. doi:10.1016/j.emc.2013.01.002. PMID: 23601485. (Emergency-medicine review covering the whole sore throat presentation — the hub-scope source for the airway-first structure, the reassessment trigger and the disposition framing.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 11, 'Li RM, Kiemeney M. Infections of the Neck. Emerg Med Clin North Am. 2019;37(1):95-107. doi:10.1016/j.emc.2018.09.003. PMID: 30454783. (Emergency-medicine source for the neck-space branches: Ludwig angina, retropharyngeal and parapharyngeal abscess, descending mediastinitis, and admission-level assignment.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 12, 'Akhavan M. Ear, Nose, Throat: Beyond Pharyngitis — Retropharyngeal Abscess, Peritonsillar Abscess, Epiglottitis, Bacterial Tracheitis, and Postoperative Tonsillectomy. Emerg Med Clin North Am. 2021;39(3):661-675. doi:10.1016/j.emc.2021.04.012. PMID: 34215408. (Scoped to the can’t-miss exclusion branches and the imaging node; it does not source the pharyngitis testing or discharge criteria.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 13, 'Bridwell RE, Koyfman A, Long B. High risk and low prevalence diseases: Adult epiglottitis. Am J Emerg Med. 2022;57:14-20. doi:10.1016/j.ajem.2022.04.018. PMID: 35489220. (Peer-reviewed evidence-based source for the adult epiglottitis recognition features, imaging limitations, antibiotic strategy and the low-quality nature of the corticosteroid evidence.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 14, 'Booth AWG, Pungsornruk K, Llewellyn S, Sturgess D, Vidhani K. Airway management of adult epiglottitis: a systematic review and meta-analysis. BJA Open. 2024;9:100250. doi:10.1016/j.bjao.2023.100250. PMID: 38230383. (Highest-quality available evidence on airway strategy in adult epiglottitis; pooled observational data, no randomised trials exist.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 15, 'Centor RM, Witherspoon JM, Dalton HP, Brody CE, Link K. The diagnosis of strep throat in adults in the emergency room. Med Decis Making. 1981;1(3):239-246. doi:10.1177/0272989X8100100304. PMID: 6763125. (Original derivation of the 4-point Centor score: tonsillar exudate, tender anterior cervical adenopathy, absence of cough, history of fever.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 16, 'McIsaac WJ, Kellner JD, Aufricht P, Vanjaka A, Low DE. Empirical validation of guidelines for the management of pharyngitis in children and adults. JAMA. 2004;291(13):1587-1595. doi:10.1001/jama.291.13.1587. PMID: 15069046. (Validation of the modified/McIsaac score, including the age adjustment that this hub refers to as the "age" criterion.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 17, 'Sadeghirad B, Siemieniuk RAC, Brignardello-Petersen R, et al. Corticosteroids for treatment of sore throat: systematic review and meta-analysis of randomised trials. BMJ. 2017;358:j3887. doi:10.1136/bmj.j3887. PMID: 28931508. (Randomised-trial basis for the single corticosteroid dose in acute sore throat.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 18, 'de Cassan S, Thompson MJ, Perera R, Glasziou PP, Del Mar CB, Heneghan CJ, Hayward G. Corticosteroids as standalone or add-on treatment for sore throat. Cochrane Database Syst Rev. 2020;5(5):CD008268. doi:10.1002/14651858.CD008268.pub3. PMID: 32356360.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 19, 'Chau JK, Seikaly HR, Harris JR, Villa-Roel C, Brick C, Rowe BH. Corticosteroids in peritonsillar abscess treatment: a blinded placebo-controlled clinical trial. Laryngoscope. 2014;124(1):97-103. doi:10.1002/lary.24283. PMID: 23794382. (Randomised-trial basis for the single corticosteroid dose in peritonsillar abscess specifically.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 20, 'Powell J, Wilson JA. An evidence-based review of peritonsillar abscess. Clin Otolaryngol. 2012;37(2):136-145. doi:10.1111/j.1749-4486.2012.02452.x. PMID: 22321140.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 21, 'Baş M, Greve J, Stelter K, et al. A randomized trial of icatibant in ACE-inhibitor-induced angioedema. N Engl J Med. 2015;372(5):418-425. doi:10.1056/NEJMoa1312524. PMID: 25629740. (Single-centre randomised trial reporting faster symptom resolution with icatibant; see [22] for the conflicting larger trial.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 22, 'Sinert R, Levy P, Bernstein JA, et al. Randomized Trial of Icatibant for Angiotensin-Converting Enzyme Inhibitor-Induced Upper Airway Angioedema. J Allergy Clin Immunol Pract. 2017;5(5):1402-1409.e3. doi:10.1016/j.jaip.2017.03.003. PMID: 28552382. (Larger multicentre randomised trial finding no benefit of icatibant over placebo in ACE-inhibitor-induced upper airway angioedema; directly conflicts with [21].)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 23, 'Chovel-Sella A, Ben Tov A, Lahav E, et al. Incidence of rash after amoxicillin treatment in children with infectious mononucleosis. Pediatrics. 2013;131(5):e1424-e1427. doi:10.1542/peds.2012-1575. PMID: 23589810. (Contemporary rash-incidence data for aminopenicillin exposure during EBV infection; reported ~33%, lower than the historically quoted >80%.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 24, 'Toti JMA, Gatti B, Hunjan I, et al. Splenic rupture or infarction associated with Epstein-Barr virus infectious mononucleosis: a systematic literature review. Swiss Med Wkly. 2023;153:40081. doi:10.57187/smw.2023.40081. PMID: 37245117. (Basis for the splenic-rupture precaution and contact-sport restriction advice given at discharge.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 25, 'Litovitz T, Whitaker N, Clark L, White NC, Marsolek M. Emerging battery-ingestion hazard: clinical implications. Pediatrics. 2010;125(6):1168-1177. doi:10.1542/peds.2009-3037. PMID: 20498173. (National Battery Ingestion Hotline case series establishing that oesophageal button-battery impaction can cause severe injury within hours — the basis for the time-critical framing in the ingestion redirect.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 26, 'FDA-approved prescribing information (DailyMed) for the antimicrobial and corticosteroid agents named in this hub. Ceftriaxone for injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=86ec0a92-a552-4a6d-9125-a54f95e43392 | Vancomycin hydrochloride for injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b01aaa02-8f1d-4b57-96a5-337503428af1 | Ampicillin and sulbactam for injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a67ae347-487d-4751-a841-b321e81db26f | Piperacillin and tazobactam for injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4d3f4b69-b0b9-494f-9cda-4537fa420d47 | Amoxicillin and clavulanate potassium: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f10634cb-6505-43f1-9b70-314c58673016 | Clindamycin hydrochloride capsules: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24595bb3-07ea-4d5f-9bb3-2c2332a1fc62 | Dexamethasone sodium phosphate injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2b626a48-c7aa-4443-9164-a08ff069ccd1 (No randomised trial establishes a preferred empiric regimen for epiglottitis, Ludwig angina or deep neck infection; agent selection in this hub is class-based and consensus-driven.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('sore-throat-hub', 27, 'FDA-approved prescribing information (DailyMed) for the targeted bradykinin-mediated angioedema agents named in this hub. Firazyr (icatibant acetate) injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ed6657ca-ab68-477a-9968-e12dc928b540 | Berinert (human C1-esterase inhibitor): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8ea0c7fe-da9d-4218-a080-0509e09bedc6 | Cinryze (human C1-esterase inhibitor): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d53a911f-070d-498a-8a61-baab72b9d0fe | Ruconest (C1 esterase inhibitor, recombinant): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=66d3fecb-32a4-7781-e053-2a91aa0a83ca (All are labelled for hereditary angioedema. Use in ACE-inhibitor-induced angioedema is off-label — see [21] and [22].)');

-- Node: tdp-pulseless (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pulseless TdP — Defibrillation","body":"**Unsynchronized defibrillation** per standard ACLS energy dosing.\n\n**⚠️ Do NOT give amiodarone** — it prolongs QT and will worsen TdP.\n\n**During resuscitation:**\n• [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades de pointes) 2 g IV push (can give rapidly in arrest), repeat 2 g at 5–15 min if TdP persists, then start an infusion\n• Standard ACLS otherwise (epinephrine, CPR)\n• Repeat defibrillation as needed\n\n**After ROSC** → proceed to acute management protocol, then [Post-Cardiac Arrest Care](#/tree/post-rosc).\n\n← [Return to Cardiac Arrest Hub](#/tree/cardiac-arrest)","citation":[1,4],"next":"tdp-pulseless-rosc","summary":"Unsynchronized defib, Mg 2g IV push (repeat at 5-15 min) then infusion, standard ACLS — do NOT give amiodarone","safetyLevel":"critical"}'::jsonb
WHERE id = 'tdp-pulseless' AND tree_id = 'torsades-de-pointes';

-- Node: tdp-unstable (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Unstable TdP — Cardioversion + Magnesium","body":"**Synchronized cardioversion** at standard energy dosing.\n\n**Simultaneously:**\n• [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades de pointes) **2 g IV over 5–15 min** (push over 1–2 min if actively deteriorating), repeat 2 g at 5–15 min if it persists, then start an infusion\n• Stop all QT-prolonging medications\n• Obtain baseline electrolytes STAT (K+, Mg, Ca, iCa)\n\n**⚠️ Do NOT give amiodarone or procainamide.**\n\nAfter initial stabilization → proceed to full magnesium protocol.","citation":[1,2],"next":"tdp-mg-protocol","summary":"Synchronized cardioversion + Mg 2g IV over 5-15min then infusion — stop all QT-prolonging meds, no amiodarone","safetyLevel":"critical"}'::jsonb
WHERE id = 'tdp-unstable' AND tree_id = 'torsades-de-pointes';

-- Node: tdp-stable (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Stable TdP — Proceed to Etiology Assessment","body":"Patient is hemodynamically stable with TdP on monitor.\n\n**Immediate actions while assessing etiology:**\n• [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades de pointes) **2 g IV over 5–15 min** — start immediately regardless of serum Mg level; repeat 2 g at 5–15 min if it persists, then start an infusion\n• Stop all potentially QT-prolonging medications\n• STAT electrolytes: K+, Mg, Ca, iCa, phosphate\n• Continuous cardiac monitoring\n• 12-lead ECG for baseline QTc measurement\n\nNow determine the underlying cause — **acquired vs congenital** — as treatment differs significantly.","citation":[1,3],"next":"tdp-etiology","summary":"Start Mg 2g IV then infusion regardless of serum level, stop QT drugs, STAT electrolytes, determine acquired vs congenital"}'::jsonb
WHERE id = 'tdp-stable' AND tree_id = 'torsades-de-pointes';

-- Node: tdp-congenital-mgmt (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Congenital LQTS — Management & Disposition","body":"**Acute stabilization:**\n• [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades de pointes) 2 g IV bolus (repeat 2 g at 5–15 min if it persists) → infusion per the magnesium protocol\n• IV beta-blocker (esmolol drip or propranolol)\n• Transvenous pacing if bradycardic or refractory\n• **Avoid:** isoproterenol, all sympathomimetics, QT-prolonging drugs\n\n**Disposition:**\n• ICU admission with continuous telemetry\n• Emergent Cardiology/Electrophysiology consult\n• Genetics referral for LQTS typing\n• ICD evaluation\n• Screen first-degree family members","citation":[3,7],"recommendation":"ICU + EP consult + genetics referral + ICD evaluation.","confidence":"recommended"}'::jsonb
WHERE id = 'tdp-congenital-mgmt' AND tree_id = 'torsades-de-pointes';

-- Node: tdp-mg-protocol (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Magnesium Protocol (EMCrit/Farkas)","body":"**The cornerstone of TdP management — give to ALL patients regardless of serum Mg level.**\n\n[Magnesium Sulfate](#/drug/magnesium-sulfate/torsades de pointes)\n\n**Guideline dose (ACLS / Tzivoni 1988):**\n• **Bolus:** 2 g IV — over 1–2 min if pulseless/unstable, over 5–15 min if perfusing\n• **Repeat:** a second 2 g bolus at 5–15 min if TdP persists or recurs\n• **Infusion — REQUIRED:** 1–4 g/hr titrated to serum Mg 3.5–5.0 mg/dL, continued ~24 h or until QTc <500 ms. A bolus alone wears off over hours and TdP recurs.\n\n**Alternative front-load (EMCrit/Farkas — expert protocol, NOT the guideline dose):**\n• **Bolus:** 4 g IV over 20 min (or faster if pulseless/unstable)\n• **Infusion:** 1 g/hr × 4 hours, then 0.5 g/hr × 20 hours\n• **Target serum Mg:** 3.5–5.0 mg/dL (much higher than standard repletion of >2)\n\n**Why give even if Mg is \"normal\"?**\n• Serum Mg does not reflect intracellular stores\n• Intracellular Mg depletion suppresses early afterdepolarizations (EADs)\n• Covers drug washout period (dofetilide t½ = 10h, amiodarone much longer)\n\n**Monitor for Mg toxicity:** loss of DTRs (first sign), respiratory depression\n**Antidote:** [Calcium Gluconate](#/drug/calcium-gluconate/hypermagnesemia) 1 g IV\n\n**Renal failure:** use intermittent boluses instead of continuous infusion.","citation":[1,2,8],"next":"tdp-mg-response","summary":"Mg 2g IV bolus (repeat at 5-15 min) then infusion 1-4 g/hr — target serum Mg 3.5-5.0, give even if \"normal\"; EMCrit alternative front-loads 4g","safetyLevel":"warning"}'::jsonb
WHERE id = 'tdp-mg-protocol' AND tree_id = 'torsades-de-pointes';

-- Node: tdp-mg-success (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Magnesium Effective — Continue Protocol","body":"**TdP has terminated. Continue magnesium infusion per protocol.**\n\n• Continue Mg infusion: 1–4 g/hr titrated to target (EMCrit taper: 1 g/hr × 4h → 0.5 g/hr × 20h)\n• Target serum Mg 3.5–5.0 mg/dL\n• Monitor serum Mg q2–4h\n\n**Now address the underlying cause:**\n• Stop all QT-prolonging drugs\n• Correct electrolytes aggressively\n• Identify and treat precipitating factors\n\nProceed to drug review and electrolyte correction.","citation":[1],"next":"tdp-stop-drugs","summary":"TdP terminated — continue Mg infusion protocol, address underlying cause"}'::jsonb
WHERE id = 'tdp-mg-success' AND tree_id = 'torsades-de-pointes';

-- Node: vafei-start (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Video-Assisted Flexible Endoscopic Intubation — Overview","body":"**Video-Assisted Flexible Endoscopic Intubation** combines video laryngoscopy to expose the airway with flexible endoscopy to guide tube delivery. [1]\n\n**WHY THIS TECHNIQUE?**\nCombines the best of both:\n• VL clears path through mouth, lifts epiglottis\n• FE provides continuous visualization through cords\n• No nasal route needed (avoids epistaxis)\n• Allows awake/breathing approach\n\n**KEY ADVANTAGES:**\n• Maintains spontaneous ventilation\n• Continuous visualization during tube passage\n• Two operators = two sets of eyes\n• Works when VL alone fails to pass tube\n\n**SUCCESS RATES:**\n• Awake flexible endoscopic intubation: 92% first-pass (nasal), 57% (oral) [3]\n• Combined video + flexible endoscopic technique addresses oral route challenges by using VL to guide the scope\n\n*Basis:* The strongest data for the combined videolaryngoscope + flexible scope technique is a single randomised trial in maxillofacial trauma (n=60): first-pass success 90% vs 60% for videolaryngoscope-guided nasotracheal intubation, intubation time 57 s vs 120 s, epistaxis 3.3% vs 30%. The primary endpoint did not survive Bonferroni adjustment (p=0.092), and the setting was the elective operating theatre, not the ED. [12] In the ED, National Emergency Airway Registry data on awake intubation (82 of 19,071 encounters) show 85% first-attempt success (95% CI 76-95%) with a flexible endoscope as the initial device in 78%. [10] ED experience with the combined system is limited to case-level reports. [18,19] The procedural sequence and operator-ergonomics detail on this page derive from a narrative expert article, not from trial data. [1]","citation":[1,2,3,10,12,18,19],"next":"vafei-indications","summary":"Video laryngoscopy + flexible endoscope combined; VL clears path, FE guides tube through cords; maintains breathing"}'::jsonb
WHERE id = 'vafei-start' AND tree_id = 'vafei';

-- Node: vafei-indications (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Indications","body":"**PRIMARY INDICATIONS:** [2,6,7]\n\n**Anatomically Difficult/Distorted Airways:**\n• Angioedema (most common indication)\n• Ludwig angina / deep neck infection\n• Oropharyngeal abscess / hematoma\n• Laryngeal or orofacial trauma\n• Airway tumors / masses\n• Prior surgery or radiation to head/neck\n\n**Intrinsic Difficult Airway Features:**\n• Micrognathia / retrognathia\n• Limited mouth opening (trismus)\n• Morbid obesity\n• Failed 3-3-2 rule\n• Mallampati IV\n• History of difficult intubation\n\n**Clinical Scenarios:**\n• \"Scared to paralyze\" - anticipated CICO risk\n• Failed VL intubation (can oxygenate)\n• Cervical spine immobility + predicted difficult airway\n• Need for continuous visualization (laryngeal trauma)\n\n*Basis:* The ranking of indications is anchored in National Emergency Airway Registry data: among ED awake intubation attempts, angioedema (32%) and non-angioedema upper airway obstruction (31%) were the two commonest indications. [10] The anatomic and intrinsic difficult-airway predictors listed here are the patient-selection criteria of the Difficult Airway Society awake tracheal intubation guideline and the ASA difficult airway guideline, both of which are consensus/Delphi products rather than prospectively validated decision rules. [7,8] The \"scared to paralyze\" category is expert framing, not a validated criterion. [6]","citation":[2,6,7,8,10],"next":"vafei-contraindications","summary":"Angioedema, Ludwig, trauma, tumors, morbid obesity, failed VL, \"scared to paralyze\" patients"}'::jsonb
WHERE id = 'vafei-indications' AND tree_id = 'vafei';

-- Node: vafei-contraindications (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Relative Contraindications","body":"**RELATIVE CONTRAINDICATIONS:** [6,8]\n\n**Visualization Barriers:**\n• Massive upper airway bleeding (obscures scope)\n• Profuse secretions / vomiting\n• Complete upper airway obstruction\n\n**Time Constraints:**\n• Severely diminished ventilation / impending arrest\n• Cannot preoxygenate adequately\n• Rapidly deteriorating airway with no time\n\n**Patient Factors:**\n• Severely uncooperative / combative (for awake approach)\n• Severe hypoxemia not responsive to BVM\n\n**IMPORTANT NOTES:**\n• Most contraindications are RELATIVE\n• Aggressive suctioning can address secretions\n• VL operator must clear blood/secretions\n• If patient deteriorates during attempt → abort → rescue airway\n\n*Basis:* No contraindication on this page is derived from a trial. Each is expert-consensus guidance drawn from the ASA difficult airway guideline and the guideline for tracheal intubation in critically ill adults, which both direct that an awake/spontaneously breathing plan be abandoned for a rescue strategy when oxygenation cannot be maintained or the airway is deteriorating faster than the technique can be completed. [8,9] The Difficult Airway Society awake tracheal intubation guideline caps attempts at three, with one further attempt by a more experienced operator (3 + 1), and directs a declared failed-ATI plan beyond that point. [7] The classification of these as RELATIVE rather than absolute is expert judgement. [6]","citation":[6,7,8,9],"next":"vafei-approach-branch","summary":"Relative CIs: massive bleeding, complete obstruction, impending arrest, severely uncooperative"}'::jsonb
WHERE id = 'vafei-contraindications' AND tree_id = 'vafei';

-- Node: vafei-approach-branch (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Select Approach","body":"Choose intubation approach based on patient status and airway assessment.\n\n*Basis:* These three approaches are NOT of equal measured performance. In the National Emergency Airway Registry analysis of 12,511 ED intubations, unadjusted first-attempt success was 61% for ketamine-only, 85% for topical anaesthesia (with or without low-dose sedation), and 90% for RSI; at least one adverse event occurred in 32%, 19%, and 14% respectively. The difference in first-pass success between the ketamine-only and topical groups was -24% (95% CI -37% to -12%), favouring topical anaesthesia. These are observational, unadjusted comparisons with substantial confounding by indication (the ketamine-only and topical groups together were only 1.4% of encounters and were selected precisely because they were expected to be difficult), so they cannot be read as causal. [11] Selecting among these approaches is a clinician judgement made under the ASA and Difficult Airway Society difficult-airway frameworks, not an algorithmic output. [7,8]","citation":[7,8,11],"options":[{"label":"Awake/Breathing approach","description":"Patient maintains spontaneous ventilation throughout","next":"vafei-prep-awake"},{"label":"RSI then flexible endoscopic rescue","description":"Standard RSI, use flexible endoscope as rescue when VL fails","next":"vafei-prep-rsi"},{"label":"Ketamine-Only (KOBI)","description":"Dissociative dose, no paralytic, breathing preserved","next":"vafei-kobi"}],"summary":"Awake = safest for distorted airways; RSI-then-flexible-endoscope for rescue; KOBI = ketamine-only breathing"}'::jsonb
WHERE id = 'vafei-approach-branch' AND tree_id = 'vafei';

-- Citations changed — DELETE and re-INSERT
DELETE FROM tree_citations WHERE tree_id = 'vafei';
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 1, 'Strayer RJ, Caputo N. How To Use Video-Assisted Flexible Endoscopic Intubation. ACEP Now. 2022 Nov 11. https://www.acepnow.com/article/how-to-use-video-assisted-flexible-endoscopic-intubation/ — SCOPE NOTE: narrative expert technique description in a membership magazine; not peer-reviewed, no trial data, no machine identifier (no PMID/DOI). Supports procedural sequence and operator-ergonomics detail only; it is not an evidence basis for success rates, dosing, or patient-selection thresholds.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 2, 'Sandefur BJ, Shappell EF, Campbell RL, Brown CA 3rd, Driver BE, Carlson JN, et al. Flexible endoscopic intubation in emergency medicine: A mixed-methods needs assessment. AEM Educ Train. 2024 Jun;8(3):e10992. PMID: 38765706. PMCID: PMC11099701. doi:10.1002/aet2.10992');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 3, 'Sandefur BJ, Driver BE, Long B. Managing Awake Intubation. Ann Emerg Med. 2025 Jan;85(1):21-30. PMID: 39480375. doi:10.1016/j.annemergmed.2024.07.017 — SCOPE NOTE: narrative review; corrected in audit from a prior entry that attributed this article to "Stolz AJ, 2024" (no such author/year exists).');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 4, 'Weingart SD. EMCrit 247 — The Dissociated Awake Intubation with my buddy, Ketamine. EMCrit. 2019 May 16. https://emcrit.org/emcrit/dissociated-awake-intubation/ — SCOPE NOTE: expert opinion podcast/blog, no machine identifier; year corrected in audit from 2018. Supports the aliquot-titration technique description only.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 5, 'Merelman AH, Perlmutter MC, Strayer RJ. Alternatives to Rapid Sequence Intubation: Contemporary Airway Management with Ketamine. West J Emerg Med. 2019 May;20(3):466-471. PMID: 31123547. PMCID: PMC6526883. doi:10.5811/westjem.2019.4.42753 — SCOPE NOTE: author string and page range corrected in audit (previously "Driver BE, et al." and "461-471").');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 6, 'Benumof JL. Management of the difficult adult airway. With special emphasis on awake tracheal intubation. Anesthesiology. 1991 Dec;75(6):1087-1110. PMID: 1824555. doi:10.1097/00000542-199112000-00021 — SCOPE NOTE: foundational 1991 review; predates video laryngoscopy and single-use flexible endoscopes. Supports difficult-airway patient-selection concepts, not contemporary device technique.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 7, 'Ahmad I, El-Boghdadly K, Bhagrath R, Hodzovic I, McNarry AF, Mir F, et al. Difficult Airway Society guidelines for awake tracheal intubation (ATI) in adults. Anaesthesia. 2020 Apr;75(4):509-528. PMID: 31729018. PMCID: PMC7078877. doi:10.1111/anae.14904');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 8, 'Apfelbaum JL, Hagberg CA, Connis RT, Abdelmalak BB, Agarkar M, Dutton RP, et al. 2022 American Society of Anesthesiologists Practice Guidelines for Management of the Difficult Airway. Anesthesiology. 2022 Jan 1;136(1):31-81. PMID: 34762729. doi:10.1097/ALN.0000000000004002 — SCOPE NOTE: replaces a prior unidentifiable entry ("UpToDate. Flexible scope intubation for anesthesia. 2024.") that carried no PMID, DOI, topic ID, version, or access date and could not be independently reviewed.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 9, 'Higgs A, McGrath BA, Goddard C, Rangasami J, Suntharalingam G, Gale R, et al. Guidelines for the management of tracheal intubation in critically ill adults. Br J Anaesth. 2018 Feb;120(2):323-352. PMID: 29406182. doi:10.1016/j.bja.2017.10.021');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 10, 'Kaisler MC, Hyde RJ, Sandefur BJ, Kaji AH, Campbell RL, Driver BE, Brown CA 3rd. Awake intubations in the emergency department: A report from the National Emergency Airway Registry. Am J Emerg Med. 2021 Nov;49:48-51. PMID: 34062317. doi:10.1016/j.ajem.2021.05.038 — NEAR registry, 19,071 encounters; awake technique on first attempt in 82 (0.4%); angioedema 32% and non-angioedema obstruction 31% were the commonest indications; flexible endoscope was the initial device in 78%; first-attempt success 85% (95% CI 76-95%), peri-intubation complications 16% (95% CI 9-26%).');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 11, 'Driver BE, Prekker ME, Reardon RF, Sandefur BJ, April MD, Walls RM, Brown CA 3rd. Success and Complications of the Ketamine-Only Intubation Method in the Emergency Department. J Emerg Med. 2021 Mar;60(3):265-272. PMID: 33308912. doi:10.1016/j.jemermed.2020.10.042 — NEAR analysis, 12,511 encounters; unadjusted first-attempt success 61% ketamine-only vs 85% topical anaesthesia vs 90% RSI; >=1 adverse event 32% vs 19% vs 14%.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 12, 'Jain K, Nair R, Goyal A, Makkar JK, Singla K, Arora S, Bhatia N. Videolaryngoscope-assisted fibreoptic intubation in anticipated difficult airways of maxillofacial trauma: a prospective randomised comparison with videolaryngoscope-guided nasotracheal intubation. Eur J Trauma Emerg Surg. 2026 Apr 27;52(1):147. PMID: 42043501. doi:10.1007/s00068-026-03191-8 — randomised trial of the combined videolaryngoscope + flexible scope technique (n=60, 30 per arm); first-pass success 90% vs 60% (unadjusted p=0.015, Bonferroni-adjusted p=0.092), intubation time 57 s vs 120 s, epistaxis 3.3% vs 30%. SCOPE NOTE: elective operating-theatre nasotracheal intubation in maxillofacial trauma; small single-centre trial whose primary endpoint did not survive multiplicity adjustment.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 13, 'Neal JM, Neal EJ, Weinberg GL. American Society of Regional Anesthesia and Pain Medicine Local Anesthetic Systemic Toxicity checklist: 2020 version. Reg Anesth Pain Med. 2021 Jan;46(1):81-82. PMID: 33148630. doi:10.1136/rapm-2020-101986');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 14, 'Rao PN, Soffin EM, Beckman JD. Comparative review of airway anesthesia and sedation methods for awake intubation. Curr Opin Anaesthesiol. 2023 Oct 1;36(5):547-559. PMID: 37314139. doi:10.1097/ACO.0000000000001273');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 15, 'KETALAR (ketamine hydrochloride) injection — US FDA Prescribing Information. Par Health USA, LLC. DailyMed setid: 14e8f864-8b8a-4e7e-8439-e510d3107063. https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=14e8f864-8b8a-4e7e-8439-e510d3107063 — SCOPE NOTE: the FDA label does not carry an awake-intubation or dissociated-awake-intubation indication; the doses used in this consult are off-label emergency-airway practice.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 16, 'Glycopyrrolate injection, solution — US FDA Prescribing Information. Piramal Critical Care Inc. DailyMed setid: 83d70378-011b-4ce3-e053-2991aa0a22be. https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=83d70378-011b-4ce3-e053-2991aa0a22be');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 17, 'Dexmedetomidine hydrochloride injection, solution — US FDA Prescribing Information. Mylan Institutional LLC. DailyMed setid: f140de5a-f13d-46b4-a742-049c63e474f5. https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f140de5a-f13d-46b4-a742-049c63e474f5');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 18, 'Miyajima S, Takahashi K, Matsuba S. Effective Use of a Combined Video Laryngoscope and Bronchoscope System in the Emergency Department for a Patient With Severe Upper Airway Obstruction Due to Angioedema: A Case Report. Cureus. 2024 Dec 23;16(12):e76285. PMID: 39850167. PMCID: PMC11754421. doi:10.7759/cureus.76285 — SCOPE NOTE: single case report; lowest tier of evidence, hypothesis-generating only.');
