INSERT INTO tree_citations (tree_id, num, text) VALUES ('vafei', 20, 'Wieczorek PM, Schricker T, Vinet B, Backman SB. Airway topicalisation in morbidly obese patients using atomised lidocaine: 2% compared with 4%. Anaesthesia. 2007 Oct;62(10):984-8. PMID: 17845648. doi:10.1111/j.1365-2044.2007.05179.x — randomised comparison in morbidly obese patients (n=27); peak plasma lidocaine 6.5 (1.0) microg/mL with 4% vs 2.8 (0.8) microg/mL with 2% (p<0.05), with comparable intubating conditions.');

-- Node: pvt-torsades-check (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Polymorphic VT in Arrest — Check QTc","body":"**Polymorphic VT in arrest** → check baseline QTc if known.\n\n**If prolonged QTc → Torsades protocol:**\n• [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades) 2 g IV push (can give rapidly in arrest), repeat 2 g at 5–15 min if it persists, then start a continuous infusion\n• **⚠️ Do NOT give amiodarone** — it prolongs QT and worsens Torsades\n• Overdrive pacing if available\n\n[Torsades de Pointes Protocol](#/tree/torsades-de-pointes)","citation":[1,2,7],"next":"pvt-rosc","summary":"If prolonged QTc: MgSO4 2g IV push, do NOT give amiodarone — it worsens Torsades; overdrive pace if available","safetyLevel":"critical"}'::jsonb
WHERE id = 'pvt-torsades-check' AND tree_id = 'ventricular-tachycardia';

-- Node: vt-poly-long-qt (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Polymorphic VT + Prolonged QTc = Torsades","body":"**Polymorphic VT with prolonged QTc = Torsades de Pointes.**\n\nTreatment is **OPPOSITE** of standard VT.\n\n**⚠️ Do NOT give amiodarone or procainamide** — they prolong QT and will worsen Torsades.\n\n**Immediate treatment:**\n• [Magnesium Sulfate](#/drug/magnesium-sulfate/torsades) 2 g IV over 5–15 min, repeat 2 g at 5–15 min if it persists, then start a continuous infusion\n• Overdrive pacing to 90–110 bpm\n• Isoproterenol infusion if pacing unavailable\n• Stop ALL QT-prolonging medications\n\n→ [Torsades de Pointes Protocol](#/tree/torsades-de-pointes)","citation":[1,3,7],"next":"vt-converted","summary":"Torsades: MgSO4 2g IV then infusion, overdrive pace 90-110bpm; do NOT give amiodarone or procainamide","safetyLevel":"critical"}'::jsonb
WHERE id = 'vt-poly-long-qt' AND tree_id = 'ventricular-tachycardia';

-- Node: vert-vitals-check (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Orthostatic Vital Signs","body":"**Get orthostatic vitals BEFORE assuming peripheral vestibular cause.** POTS and orthostatic hypotension frequently masquerade as vertigo — especially in young women and elderly.\n\n**Orthostatic criteria:**\n• **Orthostatic hypotension:** SBP drop ≥20 mmHg OR DBP drop ≥10 mmHg within 3 minutes of standing\n• **POTS:** HR increase ≥30 bpm (≥40 in adolescents) within 10 minutes of standing, without orthostatic hypotension\n\n**Pearl:** A patient who describes their \"vertigo\" as worse on standing, relieved by sitting, and lasts seconds-minutes likely has orthostatic intolerance, NOT peripheral vestibular disease. Treatment (hydration, salt, compression) is entirely different.\n\n*Basis:* The orthostatic hypotension threshold (SBP fall ≥20 mmHg or DBP fall ≥10 mmHg within 3 minutes of standing) and the POTS heart-rate criterion (≥30 bpm, ≥40 bpm in adolescents) are the 2011 consensus definitions of the American Autonomic Society / American Academy of Neurology / European Federation of Autonomic Societies [36]. These are consensus definitions, not outcome-validated decision thresholds, and they were not derived in a dizziness population. The recommendation to obtain orthostatic vitals before attributing symptoms to a vestibular cause reflects GRACE-3 diagnostic strategy for undifferentiated ED dizziness [1] and the physical-examination review in [24]; neither reports a diagnostic yield figure for this step.","citation":[1,24,36],"options":[{"label":"Normal vitals / no orthostatic change","description":"Proceed with vertigo workup","next":"vert-time-course"},{"label":"Orthostatic hypotension or POTS pattern","description":"Route to non-vestibular pathway","next":"vert-non-vertigo-exit"}],"summary":"Check orthostatic vitals before assuming vestibular cause — POTS and orthostatic hypotension masquerade as vertigo"}'::jsonb
WHERE id = 'vert-vitals-check' AND tree_id = 'vertigo';

-- Node: vert-non-vertigo-exit (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":1,"title":"Non-Vestibular Dizziness","body":"This is likely **not peripheral or central vestibular disease.** Consider alternate etiologies:\n\n**Cardiovascular:**\n• Orthostatic hypotension (volume, meds, autonomic)\n• POTS / dysautonomia\n• Arrhythmia — consider [Syncope Evaluation](#/tree/syncope)\n• Aortic stenosis, HOCM\n\n**Metabolic / Hematologic:**\n• Hypoglycemia\n• Severe anemia / GI bleed\n• Electrolyte derangement\n• Thyroid disease\n\n**Medication side effects** — review med list (antihypertensives, diuretics, alpha-blockers, SSRIs, anticholinergics).\n\n**Disposition:** Address underlying cause. If syncope-spectrum → syncope workup + risk stratification. If medication-related → adjust. Patient education on fall prevention.\n\n*Basis:* The premise for routing away from a vestibular diagnosis is that symptom-quality descriptions (\"spinning\" vs \"lightheaded\") are unreliable in acute care and should not drive the differential — demonstrated in a cross-sectional ED study in which patients gave inconsistent quality descriptors on repeat questioning [25]. The breadth of non-vestibular causes reflected here is consistent with national ED dizziness epidemiology [26], which is descriptive data only and not a validated differential-diagnosis instrument. Orthostatic and POTS definitions are consensus criteria [36]. No validated ED rule exists for excluding vestibular disease; the routing here is a diagnostic-strategy recommendation [1], not an outcome-tested pathway.","citation":[1,25,26,36],"confidence":"definitive"}'::jsonb
WHERE id = 'vert-non-vertigo-exit' AND tree_id = 'vertigo';

