INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 1, 'Edlow JA, Carpenter C, Akhter M, et al. Guidelines for reasonable and appropriate care in the emergency department 3 (GRACE-3): Acute dizziness and vertigo in the emergency department. Acad Emerg Med. 2023;30(5):442-486. doi:10.1111/acem.14728. PMID: 37166022. https://onlinelibrary.wiley.com/doi/10.1111/acem.14728 [Scope: ED diagnostic guideline for acute dizziness/vertigo. It addresses diagnostic strategy, not drug selection or dosing — do not cite GRACE-3 as the sole basis for any medication dose.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 2, 'Kattah JC, Talkad AV, Wang DZ, Hsieh YH, Newman-Toker DE. HINTS to diagnose stroke in the acute vestibular syndrome: three-step bedside oculomotor examination more sensitive than early MRI diffusion-weighted imaging. Stroke. 2009;40(11):3504-3510. doi:10.1161/STROKEAHA.109.551234. PMID: 19762709. https://www.ahajournals.org/doi/10.1161/STROKEAHA.109.551234 [Scope: n=101 AVS patients at a single stroke centre; HINTS performed by neuro-ophthalmology/neuro-otology-trained examiners. Sensitivity 100%, specificity 96%; early MRI-DWI false-negative 12%.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 3, 'Navi BB, Kamel H, Shah MP, et al. Application of the ABCD2 score to identify cerebrovascular causes of dizziness in the emergency department. Stroke. 2012;43(6):1484-1489. doi:10.1161/STROKEAHA.111.646414. PMID: 22442167.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 4, 'Oppenheim C, Stanescu R, Dormont D, et al. False-negative diffusion-weighted MR findings in acute ischemic stroke. AJNR Am J Neuroradiol. 2000;21(8):1434-1440. PMID: 11003275. (No DOI assigned by the publisher; PMID is the machine identifier.) https://pubmed.ncbi.nlm.nih.gov/11003275/');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 5, 'Simonsen CZ, Madsen MH, Schmitz ML, Mikkelsen IK, Fisher M, Andersen G. Sensitivity of diffusion- and perfusion-weighted imaging for diagnosing acute ischemic stroke is 97.5%. Stroke. 2015;46(1):98-101. doi:10.1161/STROKEAHA.114.007107. PMID: 25388415. [CORRECTED 2026-07-31: this reference previously appeared as "Sensitivity of diffusion-weighted imaging in posterior circulation. Neurology. 2015;85(20):1785-1788" — a citation that does not exist. Scope limitation: the cohort is acute ischemic stroke overall, NOT posterior-circulation-specific; do not use it as a posterior circulation DWI sensitivity source (see refs 4, 12 for that).]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 6, 'Arch AE, Weisman DC, Coca S, Nystrom KV, Wira CR 3rd, Schindler JL. Missed ischemic stroke diagnosis in the emergency department by emergency medicine and neurology services. Stroke. 2016;47(3):668-673. doi:10.1161/STROKEAHA.115.010613. PMID: 26846858. [Reports 22% of ischemic strokes initially missed overall; 37% of posterior circulation vs 16% of anterior circulation. Duplicate of ref 33 — retained because existing nodes cite both indices.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 7, 'Hilton MP, Pinder DK. The Epley (canalith repositioning) manoeuvre for benign paroxysmal positional vertigo. Cochrane Database Syst Rev. 2014;2014(12):CD003162. doi:10.1002/14651858.CD003162.pub3. PMID: 25485940. [Pooled complete symptom resolution 56% Epley vs 21% control, OR 4.42 (95% CI 2.62-7.44); authors also state a high post-treatment recurrence rate of 36%.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 8, 'Lempert T, Olesen J, Furman J, et al. Vestibular migraine: diagnostic criteria. J Vestib Res. 2012;22(4):167-172. doi:10.3233/VES-2012-0453. PMID: 23142830. (Bárány Society / IHS consensus)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 9, 'Tarnutzer AA, Berkowitz AL, Robinson KA, Hsieh YH, Newman-Toker DE. Does my dizzy patient have a stroke? A systematic review of bedside diagnosis in acute vestibular syndrome. CMAJ. 2011;183(9):E571-E592. doi:10.1503/cmaj.100174. PMID: 21576300.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 10, 'Furman JM, Barton JJS. Treatment of vertigo. UpToDate. Waltham, MA: UpToDate Inc. Accessed 2024. https://www.uptodate.com/contents/treatment-of-vertigo [Subscription point-of-care reference. No PMID or DOI exists for UpToDate topic cards; the topic URL is the only machine identifier available. Where a dose is carried, an indexed primary source is co-cited.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 11, 'Johns P, Quinn J. Clinical diagnosis of benign paroxysmal positional vertigo and vestibular neuritis. CMAJ. 2020;192(8):E182-E186. doi:10.1503/cmaj.190334. PMID: 32094268. See also Johns P, Rosenberg H. Just the Facts: How to assess a patient with constant significant vertigo and nystagmus in the emergency department. CJEM. 2020;22(4):463-467. doi:10.1017/cem.2020.34. PMID: 32456726. [REPLACED 2026-07-31: this index previously pointed to "Johns P. The Big Three of dizziness ... EMRAP / ACEP educational resources. 2019" — a non-indexed item with no PMID, DOI, or retrievable URL, and therefore not independently reviewable under FDA CDS Prong 4. Substituted with the same author''s peer-reviewed, indexed publications covering the same content.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 12, 'Saber Tehrani AS, Kattah JC, Mantokoudis G, et al. Small strokes causing severe vertigo: frequency of false-negative MRIs and nonlacunar mechanisms. Neurology. 2014;83(2):169-173. doi:10.1212/WNL.0000000000000573. PMID: 24920847. [False-negative early MRI-DWI in 53% of strokes <=10 mm.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 13, 'Kerber KA, Brown DL, Lisabeth LD, Smith MA, Morgenstern LB. Stroke among patients with dizziness, vertigo, and imbalance in the emergency department: a population-based study. Stroke. 2006;37(10):2484-2487. doi:10.1161/01.STR.0000240329.48263.0d. PMID: 16946161.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 14, 'Strupp M, Zingler VC, Arbusow V, et al. Methylprednisolone, valacyclovir, or the combination for vestibular neuritis. N Engl J Med. 2004;351(4):354-361. doi:10.1056/NEJMoa033280. PMID: 15269315. [n=141 RCT; methylprednisolone taper improved peripheral vestibular function at 12 months, valacyclovir did not, combination added nothing over steroid alone.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 15, 'Whitney SL, Alghwiri AA, Alghadir A. An overview of vestibular rehabilitation. Handb Clin Neurol. 2016;137:187-205. doi:10.1016/B978-0-444-63437-5.00013-3. PMID: 27638071.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 16, 'Dix MR, Hallpike CS. The pathology, symptomatology and diagnosis of certain common disorders of the vestibular system. Proc R Soc Med. 1952;45(6):341-354. doi:10.1177/003591575204500604. PMID: 14941845. (Original description of the positional test.) See also Dmitriew C, Bodunde O, Regis A, Lepage R, Turgeon Z, Johns P, McIsaac S, Ohle R. The use and misuse of the Dix-Hallpike test in the emergency department. CJEM. 2021;23(5):613-616. doi:10.1007/s43678-021-00110-1. PMID: 33677822. [REPLACED 2026-07-31: this index previously carried "Saccomanno S, Paoloni V, Manenti RJ, et al. Dix-Hallpike test and Epley maneuver ... Eur Arch Otorhinolaryngol. 2019;276(11):3009-3015" — a FABRICATED citation. No such article exists in that journal, volume, or page range, and the three named authors are orthodontic/dental researchers with no vestibular publications.]');
