INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 18, 'Neuhauser H, Leopold M, von Brevern M, Arnold G, Lempert T. The interrelations of migraine, vertigo, and migrainous vertigo. Neurology. 2001;56(4):436-441. doi:10.1212/wnl.56.4.436. PMID: 11222783.');
