INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 20, 'Gianoli G, Goebel J, Mowry S, Poomipannit P. Anatomic differences in the lateral vestibular nerve channels and their implications in vestibular neuritis. Otol Neurotol. 2005;26(3):489-494. doi:10.1097/01.mao.0000169787.99835.9f. PMID: 15891655. [CORRECTED 2026-07-31: this reference previously appeared as "Anatomic differences in the lateral semicircular canal. Otolaryngol Head Neck Surg. 2001;124(3):270-275" — real authors, but the title, journal, year, volume, and pages were all wrong; that journal/volume/page combination is a parotid surgery paper (PMID 11240989). Scope limitation: this is a temporal-bone study of superior vestibular nerve channel narrowing in VESTIBULAR NEURITIS. It is not a source for lateral (horizontal) canal BPPV anatomy or treatment — use refs 17/19/32 for that.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 21, 'Sajjadi H, Paparella MM. Meniere''s disease. Lancet. 2008;372(9636):406-414. doi:10.1016/S0140-6736(08)61161-7. PMID: 18675691.');
