INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 26, 'Kerber KA, Meurer WJ, West BT, Fendrick AM. Dizziness presentations in U.S. emergency departments, 1995-2004. Acad Emerg Med. 2008;15(8):744-750. doi:10.1111/j.1553-2712.2008.00189.x. PMID: 18638027. [Scope: national epidemiology of ED dizziness visits. It is NOT a diagnostic-accuracy study and is not a source for HINTS performance or for any exam recommendation.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 27, 'Nelson JA, Viirre E. The clinical differentiation of cerebellar infarction from common vertigo syndromes. West J Emerg Med. 2009;10(4):273-277. PMID: 20046249. (No DOI assigned; PMID is the machine identifier.) https://pubmed.ncbi.nlm.nih.gov/20046249/ [Note: the publication year is 2009, not 2011.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 28, 'Newman-Toker DE, Kerber KA, Hsieh YH, et al. HINTS outperforms ABCD2 to screen for stroke in acute continuous vertigo and dizziness. Acad Emerg Med. 2013;20(10):986-996. doi:10.1111/acem.12223. PMID: 24127701. [ABCD2 >=4: sensitivity 61.1%, specificity 62.3% overall. In patients aged <60 the sensitivity of ABCD2 >=4 was 28.9% — i.e. it MISSED roughly 71% of strokes in that age group.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 29, 'Hwang DY, Silva GS, Furie KL, Greer DM. Comparative sensitivity of computed tomography vs. magnetic resonance imaging for detecting acute posterior fossa infarct. J Emerg Med. 2012;42(5):559-565. doi:10.1016/j.jemermed.2011.05.101. PMID: 22305149. [CORRECTED 2026-07-31: the PMID previously recorded here (22137968) belongs to an unrelated theoretical-biology paper. Scope: n=67 patients with MRI-confirmed POSTERIOR FOSSA infarct; non-contrast CT sensitivity 41.8% (95% CI 30.1-54.4) in that posterior fossa population — this figure is not a whole-brain "acute ischemic stroke overall" sensitivity.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 30, 'Ohle R, Montpellier RA, Marchadier V, et al. Can emergency physicians accurately rule out a central cause of vertigo using the HINTS examination? A systematic review and meta-analysis. Acad Emerg Med. 2020;27(9):887-896. doi:10.1111/acem.13960. PMID: 32167642. [Population detail, verified against the abstract: the 96.7% sensitivity / 94.8% specificity pooled estimate comes from NEUROLOGISTS. The 83% sensitivity / 44% specificity estimate comes from a MIXED cohort of board-certified emergency physicians AND fellowship-trained neurologists (neuro-otology or vascular neurology). The paper does not describe either arm as "untrained," and no arm is composed purely of emergency physicians. Read any node text using the shorthand "untrained EP" against this scope note.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 31, 'Strupp M, Bisdorff A, Furman J, et al. Acute unilateral vestibulopathy/vestibular neuritis: diagnostic criteria. Consensus document of the Barany Society. J Vestib Res. 2022;32(5):389-406. doi:10.3233/VES-220201. PMID: 35723133. [Expert consensus diagnostic criteria; not a validated decision rule and not an outcome study.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 32, 'Bhattacharyya N, Gubbels SP, Schwartz SR, et al. Clinical Practice Guideline: Benign Paroxysmal Positional Vertigo (Update). Otolaryngol Head Neck Surg. 2017;156(3_suppl):S1-S47. doi:10.1177/0194599816689667. PMID: 28248609. (Recommendation AGAINST routine vestibular suppressants for BPPV; Brandt-Daroff rated inferior to canalith repositioning.) [Duplicate of ref 17 — retained because existing nodes cite both indices.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 33, 'Arch AE, Weisman DC, Coca S, Nystrom KV, Wira CR 3rd, Schindler JL. Missed ischemic stroke diagnosis in the emergency department by emergency medicine and neurology services. Stroke. 2016;47(3):668-673. doi:10.1161/STROKEAHA.115.010613. PMID: 26846858. [CORRECTED 2026-07-31: the author list previously ended "Wira CR, Greer DM." Greer DM is not an author of this paper (that name belongs to ref 29); the sixth author is Schindler JL. Duplicate of ref 6.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 34, 'Neuhauser HK, Radtke A, von Brevern M, et al. Migrainous vertigo: prevalence and impact on quality of life. Neurology. 2006;67(6):1028-1033. doi:10.1212/01.wnl.0000237539.09942.06. PMID: 17000973.');
