INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 36, 'Freeman R, Wieling W, Axelrod FB, et al. Consensus statement on the definition of orthostatic hypotension, neurally mediated syncope and the postural tachycardia syndrome. Clin Auton Res. 2011;21(2):69-72. doi:10.1007/s10286-011-0119-5. PMID: 21431947. [Source of the consensus orthostatic hypotension threshold (sustained fall of >=20 mmHg systolic or >=10 mmHg diastolic within 3 minutes of standing) and of the POTS heart-rate criterion.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 37, 'Kleindorfer DO, Towfighi A, Chaturvedi S, et al. 2021 Guideline for the Prevention of Stroke in Patients With Stroke and Transient Ischemic Attack: A Guideline From the American Heart Association/American Stroke Association. Stroke. 2021;52(7):e364-e467. doi:10.1161/STR.0000000000000375. PMID: 34024117. [Basis for secondary-prevention antiplatelet and statin recommendations after TIA/minor stroke, including short-course dual antiplatelet therapy in minor stroke/high-risk TIA.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 38, 'Orr SL, Friedman BW, Christie S, et al. Management of Adults With Acute Migraine in the Emergency Department: The American Headache Society Evidence Assessment of Parenteral Pharmacotherapies. Headache. 2016;56(6):911-940. doi:10.1111/head.12835. PMID: 27300483. [Evidence assessment underlying parenteral antidopaminergic and adjunct dosing for acute migraine in the ED. Note: this assessment addresses acute MIGRAINE; there is no dedicated ED pharmacotherapy trial base for vestibular migraine, which is itself an evidence limitation.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 39, 'Alashram AR. Effectiveness of Brandt-Daroff exercises in the treatment of benign paroxysmal positional vertigo: a systematic review of randomized controlled trials. Eur Arch Otorhinolaryngol. 2024;281(7):3371-3384. doi:10.1007/s00405-024-08502-6. PMID: 38341824. [Indexed evidence base for home Brandt-Daroff exercises as a second-line/adjunct option after canalith repositioning.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 40, 'Newman-Toker DE, Moy E, Valente E, Coffey R, Hines AL. Missed diagnosis of stroke in the emergency department: a cross-sectional analysis of a large population-based sample. Diagnosis (Berl). 2014;1(2):155-166. doi:10.1515/dx-2013-0038. PMID: 28344918. [Population-based analysis of stroke initially discharged from the ED with a benign diagnosis; the source for the young-patient and dizziness/headache-presentation misdiagnosis signal.]');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('vertigo', 41, 'Meclizine hydrochloride tablet — FDA prescribing information (Structured Product Label). DailyMed, U.S. National Library of Medicine. SETID: dab43efd-bec6-472f-b13a-1c043914dcd1. https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dab43efd-bec6-472f-b13a-1c043914dcd1 [Machine-readable label source for meclizine dosing and labelled indication. Cited alongside ref 32, which recommends AGAINST routine vestibular suppressants in BPPV.]');

-- Node: wct-hyperkalemia (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Hyperkalemic WCT","body":"**Treatment priority: membrane stabilization**\n\n**Calcium (immediate):**\n• Calcium gluconate 3g IV over 10 min\n• OR Calcium chloride 1g IV (central line preferred)\n• May repeat in 5 min if no ECG improvement\n\n**Shift potassium:**\n• Regular insulin IV — dose by hypoglycemia risk. Give WITH 25 g dextrose (D50 50 mL) unless glucose >250 mg/dL\n  - **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  - **10 units** — normal renal function AND adequate glucose\n  - Check glucose at 30, 60, 120 and 240 min\n• Albuterol 10-20mg nebulized\n• Sodium bicarbonate 50-100 mEq IV (if acidemic)\n\n**Eliminate potassium:**\n• Emergent hemodialysis if severe (K >7) or refractory\n• Kayexalate is too slow for emergency\n\n→ See [Potassium](#/tree/potassium) for full protocol","citation":[3],"next":"wct-end","summary":"Hyperkalemic WCT: calcium first (membrane stabilization), then insulin/glucose + albuterol, HD if severe","safetyLevel":"critical"}'::jsonb
WHERE id = 'wct-hyperkalemia' AND tree_id = 'wide-complex-tachycardia';

-- Node: wct-torsades (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Torsades de Pointes","body":"🛑 **DO NOT give amiodarone or procainamide**\n— They prolong QT → worsen Torsades → may be lethal\n\n**Treatment:**\n• [Magnesium sulfate](#/drug/magnesium-sulfate/torsades) 2 g IV over 5-15 min, repeat 2 g at 5-15 min if it persists\n• Can push over 1-2 min in arrest\n• Then start a continuous infusion — a bolus alone wears off and TdP recurs\n\n**If recurrent:**\n• Overdrive pacing to 90-110 bpm (shortens QT)\n• Isoproterenol if pacing unavailable (2-10 mcg/min)\n\n**Correct precipitants:**\n• Stop ALL QT-prolonging meds\n• Potassium target >4.5 mEq/L\n• Magnesium target >2.0 mEq/L\n\n→ See [Torsades de Pointes](#/tree/torsades-de-pointes) for full protocol","citation":[3,8],"next":"wct-disposition","summary":"Torsades: magnesium 2g IV then infusion. NO amiodarone/procainamide (prolong QT). Overdrive pace if recurrent.","safetyLevel":"critical"}'::jsonb
WHERE id = 'wct-torsades' AND tree_id = 'wide-complex-tachycardia';

COMMIT;